window.KB=[{"id": "qid-new", "name_en": "New Qatar ID (QID) for residents", "name_ar": "إصدار بطاقة الهوية القطرية للمقيمين", "summary_en": "Biometric national ID issued after medical fitness and enrolment. Required for banking, telecom, healthcare, and most services.", "summary_ar": "بطاقة هوية بيومترية تصدر بعد اللياقة الطبية والتسجيل. لازمة للبنوك والاتصالات والصحة ومعظم الخدمات.", "steps_en": ["Employer/sponsor opens a residency file and issues an entry/work visa.", "Complete the pre-residency medical examination at an approved Medical Commission centre.", "Attend biometric enrolment (photo, fingerprints, signature) at an MOI centre or authorised facility.", "Sponsor submits the QID/residency application on the official Metrash app or MOI portal.", "Pay government fees and choose Qatar Post delivery or collection.", "Collect the card; keep a digital copy in Metrash."], "steps_ar": ["يفتح صاحب العمل/الكفيل ملف إقامة ويصدر تأشيرة دخول/عمل.", "أكمل الفحص الطبي قبل الإقامة في مركز معتمد للجنة الطبية.", "احضر للتسجيل البيومتري (صورة، بصمات، توقيع) في مركز الداخلية أو جهة مخولة.", "يقدّم الكفيل طلب البطاقة/الإقامة عبر تطبيق مترآش الرسمي أو بوابة الداخلية.", "ادفع الرسوم واختر توصيل بريد قطر أو الاستلام.", "استلم البطاقة واحتفظ بنسخة رقمية في مترآش."], "docs_en": ["Valid passport and visa page", "Medical fitness certificate", "Passport-size photos (if requested)", "Sponsor/establishment letter and company documents", "Tenancy or accommodation proof (when required)", "Employment contract (work residency)"], "docs_ar": ["جواز سفر ساري وتأشيرة", "شهادة اللياقة الطبية", "صور شخصية إن طُلبت", "خطاب الكفيل ومستندات المنشأة", "إثبات سكن عند الحاجة", "عقد العمل (لإقامة العمل)"], "where_en": ["Official Metrash app (MOI)", "portal.moi.gov.qa", "MOI service centres"], "contacts": ["MOI 2366666", "Passports 44890333", "Hukoomi 109"], "kw": "qid qatar id بطاقة شخصية هوية مقيم اصدار جديدة fingerprint biometric مترآش metrash residency apply qatar id how do i get"}, {"id": "qid-renew", "name_en": "Qatar ID / residence permit renewal", "name_ar": "تجديد بطاقة الهوية / الإقامة", "summary_en": "Renew 1–3 years online. Sponsor usually pays. Do not let QID expire — banking, SIM, and travel are affected.", "summary_ar": "التجديد من سنة إلى ثلاث سنوات إلكترونياً. غالباً يدفع الكفيل. لا تدع البطاقة تنتهي حتى لا تتأثر البنوك والشريحة والسفر.", "steps_en": ["Ensure passport validity covers the requested residency period.", "Open official Metrash → Residency → Renew residence.", "Select person, duration (1–3 years), and delivery address.", "Pay by debit/credit card and save the receipt.", "Track delivery via Qatar Post or collect at the chosen centre."], "steps_ar": ["تأكد أن جواز السفر يغطي مدة الإقامة المطلوبة.", "افتح مترآش الرسمي ← الإقامة ← تجديد الإقامة.", "اختر الشخص والمدة (1–3 سنوات) وعنوان التوصيل.", "ادفع بالبطاقة واحفظ الإيصال.", "تتبع التوصيل عبر بريد قطر أو استلم من المركز."], "docs_en": ["Valid passport", "Current QID", "Sponsor payment capability / company standing"], "docs_ar": ["جواز ساري", "البطاقة الحالية", "قدرة الكفيل على الدفع / وضع المنشأة"], "where_en": ["Metrash app", "MOI portal", "MOI service centres"], "contacts": ["MOI 2366666"], "kw": "renew qid تجديد بطاقة إقامة residency renewal metrash"}, {"id": "visit-visa", "name_en": "Visit visas (tourist, family, business, Hayya)", "name_ar": "تأشيرات الزيارة (سياحة، عائلة، عمل، هيا)", "summary_en": "Hayya handles many tourist/event visas. Family and some business visits are applied by a Qatar-based sponsor on Metrash.", "summary_ar": "منصة هيا تغطي كثيراً من التأشيرات السياحية/الفعاليات. الزيارة العائلية وبعض زيارات العمل يقدّمها كفيل داخل قطر عبر مترآش.", "steps_en": ["Identify type: tourist (Hayya), family visit, business visit, or GCC-resident arrival facility.", "Sponsor (if required) submits passport bio page, photo, and relationship/invitation evidence on Metrash or Hayya.", "Pay the visa fee and wait for electronic approval.", "Traveller prints/saves the visa and checks airline/Hayya entry conditions.", "Do not overstay — daily fines apply and future visas can be refused."], "steps_ar": ["حدد النوع: سياحة (هيا)، زيارة عائلية، زيارة عمل، أو تسهيل لمقيمي الخليج.", "يقدّم الكفيل إن لزم صورة الجواز والصورة وإثبات الصلة/الدعوة عبر مترآش أو هيا.", "ادفع الرسم وانتظر الموافقة الإلكترونية.", "يحفظ المسافر التأشيرة ويراجع شروط الدخول والخطوط الجوية.", "لا تتجاوز مدة الإقامة — تُفرض غرامة يومية وقد تُرفض التأشيرات لاحقاً."], "docs_en": ["Passport (usually 6+ months validity)", "Photo", "Sponsor QID and proof of relationship/invitation", "Return ticket / hotel as requested"], "docs_ar": ["جواز (صلاحية 6 أشهر غالباً)", "صورة", "هوية الكفيل وإثبات الصلة/الدعوة", "تذكرة عودة/حجز فندق إن طُلب"], "where_en": ["hayya.qa", "Metrash", "MOI portal"], "contacts": ["MOI 2366666", "Hukoomi 109"], "kw": "visa visit tourist hayya هيا زيارة عائلية سياحة business gcc arrival"}, {"id": "work-visa", "name_en": "Work visa and first-time residency", "name_ar": "تأشيرة العمل والإقامة لأول مرة", "summary_en": "Employer obtains a labour quota/work permit then an MOI work entry visa. After arrival: medical, biometrics, QID.", "summary_ar": "يحصل صاحب العمل على تصريح عمل/حصة ثم تأشيرة دخول للعمل. بعد الوصول: الفحص الطبي والبصمة والبطاقة.", "steps_en": ["Company has a valid CR, establishment card, and labour file with available quota.", "Ministry of Labour work-permit / contract attestation.", "MOI issues work entry visa; worker travels to Qatar.", "Medical Commission exam + vaccinations if required.", "Biometrics and residency/QID issuance; health card and bank account follow."], "steps_ar": ["يجب أن يكون للشركة سجل تجاري وبطاقة منشأة وملف عمل بحصة متاحة.", "تصريح العمل/تصديق العقد لدى وزارة العمل.", "تصدر الداخلية تأشيرة دخول للعمل ويسافر العامل.", "فحص اللجنة الطبية والتطعيمات إن لزم.", "البصمة ثم الإقامة/البطاقة، تليها البطاقة الصحية والحساب البنكي."], "docs_en": ["Passport", "Education/experience certificates (attested if requested)", "Offer/contract", "Company CR and establishment card", "Photos"], "docs_ar": ["جواز", "شهادات علمية/خبرة مصدّقة إن طُلبت", "عرض/عقد", "السجل وبطاقة المنشأة", "صور"], "where_en": ["MOL digital services", "MOI/Metrash", "Medical Commission"], "contacts": ["MOL 16505", "MOI 2366666"], "kw": "work visa تأشيرة عمل employment residency تصريح documents passport contract offer medical"}, {"id": "sponsorship-transfer", "name_en": "Change of employer / sponsorship transfer", "name_ar": "نقل الكفالة / تغيير صاحب العمل", "summary_en": "2020 reforms removed the general NOC requirement for most private-sector workers. Notice period still applies. Then update QID.", "summary_ar": "إصلاحات 2020 ألغت اشتراط عدم الممانعة العام لمعظم عمال القطاع الخاص. فترة الإخطار ما زالت سارية. ثم تُحدَّث البطاقة.", "steps_en": ["Confirm you are not in a restricted category (some domestic workers and special contracts differ).", "New employer files a transfer / new work-permit request on MOL systems.", "Serve contractual notice (commonly 1 month) or agree a waiver in writing.", "Once labour transfer is approved, complete MOI residency transfer and new QID.", "Move WPS salary to the new employer and update bank/SIM if needed."], "steps_ar": ["تأكد أنك لست من فئة مقيدة (بعض العمالة المنزلية والعقود الخاصة تختلف).", "يقدّم صاحب العمل الجديد طلب النقل/التصريح على أنظمة العمل.", "نفّذ فترة الإخطار (غالباً شهر) أو اتفق على الإعفاء كتابة.", "بعد الموافقة العمالية أكمل نقل الإقامة والبطاقة الجديدة.", "انقل الراتب عبر نظام حماية الأجور وحدّث البنك/الشريحة إن لزم."], "docs_en": ["QID", "Passport", "Current and new contracts", "Company documents of new employer"], "docs_ar": ["الهوية", "الجواز", "العقد الحالي والجديد", "مستندات الشركة الجديدة"], "where_en": ["mol.gov.qa", "Metrash"], "contacts": ["MOL 16505"], "kw": "kafala transfer sponsorship نقل كفالة noc تغيير عمل employer"}, {"id": "exit-permit", "name_en": "Exit permits after 2020 reforms", "name_ar": "تصريح الخروج بعد إصلاحات 2020", "summary_en": "Most employees no longer need an exit permit. Limited exceptions remain for certain roles (e.g. some senior/sensitive posts listed by the employer with MOL).", "summary_ar": "معظم الموظفين لم يعودوا بحاجة لتصريح خروج. تبقى استثناءات محدودة لبعض المناصب (مثل مناصب عليا/حساسة يبلغ عنها صاحب العمل للوزارة).", "steps_en": ["Check your status on Metrash / MOI before booking non-refundable tickets.", "If you are in an excepted category, the employer must process the permit digitally.", "Domestic workers have a specific notice-before-travel framework — confirm current MOL guidance.", "Always travel with valid QID and passport."], "steps_ar": ["تحقق من حالتك على مترآش/الداخلية قبل حجز تذاكر غير قابلة للاسترداد.", "إذا كنت من فئة مستثناة يعالج صاحب العمل التصريح رقمياً.", "للعمالة المنزلية إطار إخطار قبل السفر — راجع إرشاد وزارة العمل الحالي.", "سافر دائماً بجواز وبطاقة ساريين."], "docs_en": ["QID", "Passport", "Employer action if excepted"], "docs_ar": ["الهوية", "الجواز", "إجراء صاحب العمل إن وُجد استثناء"], "where_en": ["Metrash", "MOI portal"], "contacts": ["MOI 2366666", "MOL 16505"], "kw": "exit permit تصريح خروج travel travelban"}, {"id": "driving-license", "name_en": "Driving licence (new, GCC exchange, foreign conversion)", "name_ar": "رخصة القيادة (جديدة، استبدال خليجي، تحويل أجنبي)", "summary_en": "QID required. GCC licences generally exchanged. Other nationalities: conversion or full tests at Traffic (Madinat Khalifa and authorised schools).", "summary_ar": "الهوية لازمة. رخص الخليج تُستبدل عموماً. الجنسيات الأخرى: تحويل أو اختبارات كاملة في المرور (مدينة خليفة والمدارس المعتمدة).", "steps_en": ["Hold a valid QID and pass an approved eye test.", "If GCC: apply for licence exchange with original licence and translation if needed.", "If eligible foreign licence: follow current MOI conversion path (may include theory and/or road test).", "If no eligible licence: enrol in a licensed driving school, pass theory then practical.", "Pay fees on Metrash / Traffic and collect or receive the licence."], "steps_ar": ["احمل هوية سارية واجتز فحص النظر المعتمد.", "إن كانت الرخصة خليجية: قدّم للاستبدال مع الأصل والترجمة إن لزم.", "إن كانت رخصة أجنبية مؤهلة: اتبع مسار التحويل الحالي (قد يشمل النظري و/أو العملي).", "إن لم توجد رخصة مؤهلة: التحق بمدرسة معتمدة واجتز النظري ثم العملي.", "ادفع الرسوم عبر مترآش/المرور واستلم الرخصة."], "docs_en": ["QID", "Passport", "Original foreign/GCC licence", "Eye-test report", "Sponsor NOC if requested", "Photos"], "docs_ar": ["الهوية", "الجواز", "الرخصة الأصلية", "تقرير النظر", "عدم ممانعة الكفيل إن طُلبت", "صور"], "where_en": ["Traffic Department, Madinat Khalifa", "Metrash", "Licensed driving schools"], "contacts": ["MOI 2366666"], "kw": "driving licence license رخصة قيادة convert exchange traffic مرور qid madinat khalifa"}, {"id": "vehicle-reg", "name_en": "Vehicle registration, Fahes inspection, traffic fines", "name_ar": "تسجيل المركبات وفحص فاحص والمخالفات", "summary_en": "Istimara renewal needs a passing Fahes inspection. Fines and black points are paid/viewed on Metrash. Early payment can reduce some fines.", "summary_ar": "تجديد الاستمارة يحتاج اجتياز فحص فاحص. المخالفات والنقاط السوداء على مترآش. الدفع المبكر قد يخفض بعض الغرامات.", "steps_en": ["Book Fahes inspection before istimara expiry.", "Repair any failed items and retest.", "Renew registration on Metrash and pay fees + any outstanding fines.", "Display the new sticker/istimara as required."], "steps_ar": ["احجز فحص فاحص قبل انتهاء الاستمارة.", "أصلح بنود الرسوب وأعد الفحص.", "جدّد التسجيل على مترآش وادفع الرسوم وأي مخالفات قائمة.", "أظهر الملصق/الاستمارة حسب التعليمات."], "docs_en": ["QID", "Istimara", "Insurance", "Fahes report"], "docs_ar": ["الهوية", "الاستمارة", "التأمين", "تقرير فاحص"], "where_en": ["Fahes centres", "Metrash", "MOI portal"], "contacts": ["MOI 2366666"], "kw": "fahes istimara مركبة تسجيل مخالفات fines black points"}, {"id": "metrash", "name_en": "Metrash official MOI app", "name_ar": "تطبيق مترآش الرسمي لوزارة الداخلية", "summary_en": "MOI retired the older Metrash2 brand and operates the official Metrash app (iOS/Android) for 400+ services: QID, visas, traffic, licences, certificates.", "summary_ar": "أوقفت الداخلية علامة مترآش2 القديمة وتشغّل تطبيق مترآش الرسمي لأكثر من 400 خدمة: الهوية والتأشيرات والمرور والرخص والشهادات.", "steps_en": ["Download 'Metrash' from the official App Store / Google Play (verify publisher is Ministry of Interior).", "Register with QID and a mobile number registered to that QID.", "Complete OTP / extra verification steps shown in the app.", "Enable notifications for QID, licence, and vehicle expiry."], "steps_ar": ["حمّل «مترآش» من المتجر الرسمي وتأكد أن الناشر وزارة الداخلية.", "سجّل بالهوية ورقم جوال مسجّل عليها.", "أكمل رمز التحقق وخطوات التفعيل.", "فعّل التنبيهات لانتهاء الهوية والرخصة والمركبة."], "docs_en": ["QID", "Qatari mobile number in your name"], "docs_ar": ["الهوية", "رقم قطري باسمك"], "where_en": ["App Store", "Google Play", "portal.moi.gov.qa"], "contacts": ["MOI e-services 2342000", "MOI 2366666"], "kw": "metrash metrash2 مترآش تطبيق الداخلية"}, {"id": "civil-defense", "name_en": "Civil Defence fire-safety certificates", "name_ar": "شهادات الدفاع المدني للسلامة من الحريق", "summary_en": "Required for many commercial fit-outs, hotels, warehouses, and building occupancy.", "summary_ar": "مطلوبة لكثير من التشطيبات التجارية والفنادق والمستودعات وإشغال المباني.", "steps_en": ["Submit architectural/MEP drawings via Civil Defence digital channels.", "Install approved fire systems; request inspection.", "Rectify remarks and collect the certificate; keep it valid for licence renewal."], "steps_ar": ["قدّم المخططات عبر قنوات الدفاع المدني الرقمية.", "ركّب أنظمة الحريق المعتمدة واطلب الكشف.", "عالج الملاحظات واستلم الشهادة وجدّدها مع الرخص."], "docs_en": ["CR", "Drawings", "Contractor certificates", "Previous certificate if renewal"], "docs_ar": ["السجل التجاري", "المخططات", "شهادات المقاول", "الشهادة السابقة إن وجدت"], "where_en": ["General Directorate of Civil Defence"], "contacts": ["Civil Defence 44895191", "Emergency 999"], "kw": "civil defence fire شهادة دفاع مدني حريق"}, {"id": "work-permit", "name_en": "Work permits: issue, renew, cancel", "name_ar": "تصاريح العمل: إصدار وتجديد وإلغاء", "summary_en": "Employer-managed on Ministry of Labour platforms. Linked to attested contract and WPS.", "summary_ar": "يديرها صاحب العمل على منصات وزارة العمل وترتبط بالعقد المصدّق ونظام حماية الأجور.", "steps_en": ["Open/maintain a company labour file and quota.", "Submit worker data, contract, and passport copy.", "Pay permit fees; print/download approval.", "To cancel: settle wages and dues, then file cancellation so the worker can transfer or exit."], "steps_ar": ["افتح/حافظ على ملف المنشأة والحصة.", "قدّم بيانات العامل والعقد وصورة الجواز.", "ادفع الرسوم وحمل الموافقة.", "للإلغاء: سوِّ الأجور والمستحقات ثم قدّم الإلغاء ليتمكن العامل من النقل أو المغادرة."], "docs_en": ["Establishment card", "CR", "Contract", "Passport", "QID if already resident"], "docs_ar": ["بطاقة المنشأة", "السجل", "العقد", "الجواز", "الهوية إن وُجدت"], "where_en": ["mol.gov.qa digital services"], "contacts": ["16505"], "kw": "work permit تصريح عمل تجديد إلغاء"}, {"id": "labour-contract", "name_en": "Labour contract registration", "name_ar": "تسجيل عقد العمل", "summary_en": "Contracts must be attested/registered. Arabic version prevails. Standard terms cannot undercut the Labour Law.", "summary_ar": "يجب تصديق/تسجيل العقود. النسخة العربية هي المعتمدة. لا يجوز أن تنتقص الشروط من قانون العمل.", "steps_en": ["Use the ministry standard electronic contract where required.", "State basic wage, allowances, job title, hours, and leave.", "Both parties sign; employer submits for attestation.", "Keep a copy; it is used for WPS, visas, and disputes."], "steps_ar": ["استخدم العقد الإلكتروني النموذجي حيث يُطلب.", "بيّن الأجر الأساسي والبدلات والمسمى وساعات العمل والإجازات.", "يوقع الطرفان ويقدّمه صاحب العمل للتصديق.", "احتفظ بنسخة فهي أساس حماية الأجور والتأشيرات والنزاعات."], "docs_en": ["Passport/QID", "Offer letter", "Company credentials"], "docs_ar": ["الجواز/الهوية", "خطاب العرض", "مستندات الشركة"], "where_en": ["MOL platforms"], "contacts": ["16505"], "kw": "contract عقد عمل تصديق attestation"}, {"id": "wps", "name_en": "Wage Protection System (WPS)", "name_ar": "نظام حماية الأجور", "summary_en": "Salaries must be paid through approved banks/exchange houses into the worker’s account, generally within 7 days of the due date.", "summary_ar": "يجب دفع الرواتب عبر بنوك/شركات صرافة معتمدة إلى حساب العامل، عموماً خلال 7 أيام من تاريخ الاستحقاق.", "steps_en": ["Worker opens a personal bank account with QID.", "Employer uploads the WPS file each cycle for the full contractual wage.", "Keep payslips. Delayed or partial WPS filings can block new permits."], "steps_ar": ["يفتح العامل حساباً شخصياً بالهوية.", "يرفع صاحب العمل ملف الحماية كل دورة بكامل الأجر التعاقدي.", "احتفظ بكشوف الراتب. التأخير أو النقص قد يوقف التصاريح الجديدة."], "docs_en": ["Bank IBAN", "QID", "Contract wage breakdown"], "docs_ar": ["آيبان", "الهوية", "تفصيل الأجر في العقد"], "where_en": ["Employer payroll + approved banks"], "contacts": ["16505"], "kw": "wps حماية الأجور راتب salary unpaid"}, {"id": "minimum-wage", "name_en": "Minimum wage (Law 17 of 2020)", "name_ar": "الحد الأدنى للأجور (القانون 17 لسنة 2020)", "summary_en": "QAR 1,000 basic + QAR 500 housing if not provided + QAR 300 food if not provided. Applies to all workers including domestic workers from March 2021.", "summary_ar": "1000 ريال أساسي + 500 بدل سكن إن لم يُوفَّر + 300 بدل غذاء إن لم يُوفَّر. يسري على الجميع بما فيهم العمالة المنزلية من مارس 2021.", "steps_en": ["Check your attested contract: basic vs allowances.", "If housing or food is provided in kind, those allowances need not be paid in cash.", "If cash pay is below the legal floor, file a labour complaint (16505)."], "steps_ar": ["راجع عقدك المصدّق: الأساسي مقابل البدلات.", "إذا وُفّر السكن أو الطعام عينياً فلا يلزم دفع البدل نقداً.", "إذا كان الأجر النقدي دون الحد القانوني فقدّم شكوى (16505)."], "docs_en": ["Contract", "WPS slips", "QID"], "docs_ar": ["العقد", "كشوف الحماية", "الهوية"], "where_en": ["Law 17/2020", "MOL"], "contacts": ["16505"], "kw": "minimum wage حد أدنى 1000 500 300 بدل سكن غذاء"}, {"id": "gratuity", "name_en": "End-of-service gratuity", "name_ar": "مكافأة نهاية الخدمة", "summary_en": "Article 54: after 1 year, at least 3 weeks (21 days) of last basic wage per year, pro-rata for months. Not 4 weeks after 5 years under current law.", "summary_ar": "المادة 54: بعد سنة، ثلاثة أسابيع (21 يوماً) على الأقل من آخر أساسي عن كل سنة مع التناسب للأشهر. ليست 4 أسابيع بعد 5 سنوات في القانون الحالي.", "steps_en": ["Confirm last basic wage (allowances usually excluded unless contract says otherwise).", "Count completed years minus unpaid leave.", "Apply: basic × (21/30) × years.", "Employer may deduct proven worker debts. Article 61 dismissals may lose gratuity.", "Dues should be paid by the day after termination (or within 7 days if the worker left without notice)."], "steps_ar": ["حدد آخر أجر أساسي (البدلات تُستبعد عادة ما لم ينص العقد).", "احسب السنوات مكتملة بعد خصم الإجازة بدون راتب.", "الصيغة: الأساسي × (21/30) × السنوات.", "يجوز خصم ديون العامل المثبتة. الفصل بالمادة 61 قد يسقط المكافأة.", "تُدفع المستحقات في اليوم التالي لانتهاء الخدمة (أو خلال 7 أيام إذا ترك العامل دون إخطار)."], "docs_en": ["Contract", "Salary certificates", "Resignation/termination letter"], "docs_ar": ["العقد", "شهادات الراتب", "خطاب الاستقالة/الإنهاء"], "where_en": ["Employer payroll; disputes at MOL"], "contacts": ["16505"], "kw": "gratuity مكافأة نهاية الخدمة 21 eos end of service"}, {"id": "working-hours", "name_en": "Working hours, overtime, leave, probation", "name_ar": "ساعات العمل والإضافي والإجازات والتجربة", "summary_en": "48h/week, 8h/day typical max. Ramadan 6h/day for Muslim workers. Overtime usually 125%. Annual leave 3 weeks after 1 year. Sick leave 2 weeks full + 4 weeks half. Probation max 6 months.", "summary_ar": "الحد الشائع 48 ساعة/أسبوع و8/يوم. رمضان 6 ساعات للعمال المسلمين. الإضافي عادة 125%. الإجازة السنوية 3 أسابيع بعد سنة. المرضية أسبوعان كاملان + 4 أنصاف. التجربة حدها 6 أشهر.", "steps_en": ["Check your contract for hours and rest day.", "Overtime must be compensated at the legal premium.", "Annual leave: at least three weeks after one year of service (some employers grant more after 5 years by policy, not as the old statutory ladder).", "Sick leave: up to 2 weeks full pay then 4 weeks half pay per year with medical proof.", "Probation cannot exceed 6 months; termination during probation follows the contract and law.", "Non-compete clauses, if any, must be reasonable; commonly discussed maximum around 2 years and limited geography/activity."], "steps_ar": ["راجع العقد لساعات العمل ويوم الراحة.", "يجب تعويض الإضافي بالعلاوة القانونية.", "الإجازة السنوية: ثلاثة أسابيع على الأقل بعد سنة (بعض أصحاب العمل يمنحون أكثر بعد 5 سنوات كسياسة لا كسلّم قانوني قديم).", "المرضية: حتى أسبوعين بأجر كامل ثم 4 أسابيع بنصف أجر في السنة مع إثبات طبي.", "التجربة لا تتجاوز 6 أشهر.", "شرط عدم المنافسة إن وُجد يجب أن يكون معقولاً؛ يُذكر غالباً حد أقصى نحو سنتين مع حصر النشاط/المكان."], "docs_en": ["Contract", "Timesheets", "Medical reports for sick leave"], "docs_ar": ["العقد", "سجلات الدوام", "التقارير الطبية"], "where_en": ["Labour Law 14/2004 as amended"], "contacts": ["16505"], "kw": "overtime ساعات إجازة مرضية تجربة ramadan probation leave حقوق العامل worker rights labour law"}, {"id": "labour-dispute", "name_en": "Labour complaints and mediation", "name_ar": "الشكاوى العمالية والوساطة", "summary_en": "Start at MOL (16505 / digital). Mediation first, then labour court. Keep evidence. Passport retention is unlawful.", "summary_ar": "ابدأ بوزارة العمل (16505 / الرقمي). الوساطة أولاً ثم المحكمة العمالية. احتفظ بالأدلة. احتجاز الجواز غير قانوني.", "steps_en": ["Gather contract, WPS, chats, and QID.", "File online or at a labour relations office; attend mediation.", "If no settlement, the file can be referred to court.", "You may seek private legal advice for complex cases."], "steps_ar": ["اجمع العقد وكشوف الأجور والمحادثات والهوية.", "قدّم إلكترونياً أو في مكتب علاقات العمل واحضر الوساطة.", "إن تعذر الصلح يُحال الملف للمحكمة.", "يمكنك استشارة محامٍ في القضايا المعقدة."], "docs_en": ["QID", "Contract", "Payslips", "Evidence of claim"], "docs_ar": ["الهوية", "العقد", "كشوف الراتب", "أدلة المطالبة"], "where_en": ["MOL offices / digital"], "contacts": ["16505"], "kw": "complaint شكوى عمالية court mediation نزاع"}, {"id": "worker-rights", "name_en": "Worker rights in Qatar", "name_ar": "حقوق العامل في قطر", "summary_en": "Core rights: minimum wage QAR 1,000 + allowances, WPS salary, 48-hour week, paid leave, 21-day gratuity after one year, free job change after notice, and the right to complain on 16505. Passport retention is unlawful.", "summary_ar": "الحقوق الأساسية: حد أدنى 1000 ريال مع البدلات، حماية الأجور، أسبوع 48 ساعة، إجازة مدفوعة، مكافأة 21 يوماً بعد سنة، حرية تغيير العمل بعد الإخطار، والشكوى على 16505. احتجاز الجواز غير قانوني.", "steps_en": ["Check your attested contract against Law 14/2004 and the 2020 wage/mobility reforms.", "Confirm WPS deposits match the contractual wage every month.", "Keep copies of QID, contract, and payslips.", "Escalate unpaid wages, hours, or housing issues to MOL 16505."], "steps_ar": ["طابق عقدك المصدّق مع القانون 14/2004 وإصلاحات 2020 للأجور والتنقل.", "تأكد أن تحويلات حماية الأجور تطابق الأجر التعاقدي كل شهر.", "احتفظ بنسخ الهوية والعقد وكشوف الراتب.", "صعّد الأجور المتأخرة أو الساعات أو السكن إلى 16505."], "docs_en": ["QID", "Contract", "WPS slips"], "docs_ar": ["الهوية", "العقد", "كشوف الحماية"], "where_en": ["mol.gov.qa", "16505"], "contacts": ["16505"], "kw": "حقوق العامل worker rights labour rights قانون العمل 1000"}, {"id": "worker-housing", "name_en": "Worker accommodation standards", "name_ar": "معايير سكن العمال", "summary_en": "Employer-provided camps must meet space, hygiene, safety, and inspection rules. Report violations to MOL.", "summary_ar": "يجب أن يستوفي السكن المقدم من صاحب العمل قواعد المساحة والنظافة والسلامة والتفتيش. بلّغ الوزارة عن المخالفات.", "steps_en": ["Compare your housing with the published workers’ accommodation standards.", "Raise the issue internally in writing.", "Escalate to MOL inspections / 16505 with photos and address."], "steps_ar": ["قارن سكنك بالمعايير المنشورة.", "اطرح المشكلة داخلياً كتابة.", "صعّد لتفتيش الوزارة / 16505 مع صور والعنوان."], "docs_en": ["QID", "Photos", "Camp address", "Contract housing clause"], "docs_ar": ["الهوية", "صور", "عنوان السكن", "بند السكن في العقد"], "where_en": ["MOL inspection"], "contacts": ["16505"], "kw": "accommodation سكن عمال camp معايير"}, {"id": "cr-application", "name_en": "Commercial Registration (CR)", "name_ar": "السجل التجاري", "summary_en": "Issued by MOCI via the National Single Window after name reservation and constitutional documents.", "summary_ar": "يصدر عن وزارة التجارة عبر النافذة الواحدة بعد حجز الاسم ومستندات التأسيس.", "steps_en": ["Reserve a unique trade name on the MOCI portal (often 2–3 working days).", "Choose legal form (WLL/LLC, partnership, branch, representative office).", "Prepare bilingual Memorandum/Articles; notarise as required.", "Submit CR application with IDs, lease, and activity list.", "Pay fees; download CR; then municipal licence, tax number, establishment card."], "steps_ar": ["احجز اسماً تجارياً فريداً على بوابة الوزارة (غالباً 2–3 أيام عمل).", "اختر الشكل القانوني (ذات مسؤولية محدودة، تضامن، فرع، مكتب تمثيل).", "أعد عقد التأسيس باللغتين ووثّقه عند الحاجة.", "قدّم طلب السجل مع الهويات والإيجار وقائمة الأنشطة.", "ادفع الرسوم وحمل السجل ثم الرخصة البلدية والرقم الضريبي وبطاقة المنشأة."], "docs_en": ["Partners’ passports/QIDs", "AoA/MoA", "Lease", "Name reservation", "Capital evidence if required"], "docs_ar": ["جوازات/هويات الشركاء", "عقد التأسيس", "عقد الإيجار", "حجز الاسم", "إثبات رأس المال إن لزم"], "where_en": ["MOCI Single Window", "moci.gov.qa"], "contacts": ["MOCI 16001", "Consumer 8005000"], "kw": "cr commercial registration سجل تجاري شركة"}, {"id": "llc-formation", "name_en": "LLC / WLL company formation and foreign ownership", "name_ar": "تأسيس شركة ذات مسؤولية محدودة وملكية الأجانب", "summary_en": "Common form: 2–50 partners. Law 1 of 2019 allows 100% foreign ownership in many activities. Some strategic activities still need a Qatari partner. Historic QAR 200,000 capital is still cited for many WLLs; confirm current MOCI activity rules.", "summary_ar": "الشكل الشائع: 2–50 شريكاً. القانون 1 لسنة 2019 يسمح بملكية أجنبية 100% في أنشطة كثيرة. أنشطة استراتيجية قد تحتاج شريكاً قطرياً. ما زال يُذكر رأس مال 200,000 ريال لكثير من الشركات؛ أكد قواعد النشاط الحالية.", "steps_en": ["Check if your ISIC activity is on the 100% foreign-ownership list.", "If not, structure 51/49 with a Qatari partner or use QFC/free zone.", "Notarise AoA, deposit capital if required, obtain CR and licences."], "steps_ar": ["تحقق إن كان نشاطك ضمن قائمة الملكية الأجنبية 100%.", "إن لم يكن، استخدم هيكل 51/49 أو مركز قطر للمال/منطقة حرة.", "وثّق العقد وأودع رأس المال إن لزم واستخرج السجل والرخص."], "docs_en": ["IDs", "AoA", "Bank capital letter", "Lease", "Approvals for regulated activities"], "docs_ar": ["الهويات", "عقد التأسيس", "خطاب رأس المال", "الإيجار", "موافقات الأنشطة المنظمة"], "where_en": ["MOCI", "QFC", "QFZA", "QSTP"], "contacts": ["16001"], "kw": "llc wll تأسيس شركة 51% 200000 foreign ownership"}, {"id": "free-zones", "name_en": "Qatar Free Zones, QFC, and QSTP", "name_ar": "المناطق الحرة ومركز قطر للمال وواحة العلوم", "summary_en": "QFZA (Ras Bufontas, Umm Alhoul): 100% foreign ownership, customs/tax incentives, profit repatriation. QFC: onshore legal/regulatory hub for financial and professional firms, English common-law style court. QSTP: tech/R&D focus.", "summary_ar": "هيئة المناطق الحرة (راس بوفنطاس وأم الحول): ملكية أجنبية 100% وحوافز جمركية/ضريبية وإعادة أرباح. مركز قطر للمال: بيئة قانونية للشركات المالية والمهنية ومحكمة بأسلوب القانون العام. واحة العلوم: تقنية وبحث.", "steps_en": ["Match activity to QFZA vs QFC vs QSTP vs mainland.", "Submit a business plan and KYC to the chosen authority.", "Lease office space in the zone, obtain licence, then visas via the zone’s window."], "steps_ar": ["طابق النشاط مع المنطقة الحرة أو مركز قطر للمال أو الواحة أو البر.", "قدّم خطة العمل واعرف عميلك للجهة المختارة.", "استأجر مكتباً في النطاق واستخرج الرخصة ثم التأشيرات عبر نافذتها."], "docs_en": ["Passport KYC", "CV of managers", "Business plan", "Lease"], "docs_ar": ["اعرف عميلك للجواز", "سير المديرين", "خطة العمل", "الإيجار"], "where_en": ["qfc.qa", "qfz.gov.qa", "qstp.org.qa"], "contacts": ["QFC switchboard via qfc.qa"], "kw": "qfc qfza qstp free zone منطقة حرة 100%"}, {"id": "trademark", "name_en": "Trademark registration", "name_ar": "تسجيل العلامة التجارية", "summary_en": "File at MOCI IP. Protection after publication and grant, renewable.", "summary_ar": "يُقدَّم لدى الملكية الفكرية بالوزارة. الحماية بعد النشر والمنح وقابلة للتجديد.", "steps_en": ["Search existing marks", "File classes and logo", "Respond to office actions", "Publish and receive certificate"], "steps_ar": ["ابحث عن علامات قائمة", "قدّم الفئات والشعار", "الرد على الملاحظات", "النشر ثم الشهادة"], "docs_en": ["Logo", "Applicant CR/ID", "POA if agent"], "docs_ar": ["الشعار", "سجل/هوية مقدم الطلب", "توكيل إن وُجد وكيل"], "where_en": ["MOCI Intellectual Property"], "contacts": ["16001"], "kw": "trademark علامة تجارية ip"}, {"id": "consumer-protection", "name_en": "Consumer protection complaints", "name_ar": "شكاوى حماية المستهلك", "summary_en": "File against shops, cars, electronics, and services. Hotline 800 5000 / 16001.", "summary_ar": "قدّم ضد المتاجر والسيارات والإلكترونيات والخدمات. 8005000 / 16001.", "steps_en": ["Keep invoice and warranty", "Complain to the seller first", "Escalate to Consumer Protection with evidence"], "steps_ar": ["احتفظ بالفاتورة والضمان", "اشتكِ للتاجر أولاً", "صعّد لحماية المستهلك مع الأدلة"], "docs_en": ["Invoice", "Photos", "QID", "Correspondence"], "docs_ar": ["فاتورة", "صور", "هوية", "مراسلات"], "where_en": ["MOCI Consumer Protection"], "contacts": ["8005000", "16001"], "kw": "consumer حماية مستهلك شكوى تاجر"}, {"id": "health-card", "name_en": "Health card (PHCC / HMC)", "name_ar": "البطاقة الصحية", "summary_en": "Links residents to public primary care. Apply via Nar’aakom, Hukoomi, or a health centre. Qataris increasingly use National ID in public facilities.", "summary_ar": "تربط المقيم بالرعاية الأولية الحكومية. التقديم عبر نرعاكم أو حكومي أو المركز الصحي. المواطنون يتجهون لاستخدام البطاقة الوطنية.", "steps_en": ["Get your QID first.", "Apply on Nar’aakom or at your catchment PHCC with photo and QID.", "Pay the annual fee and collect/print the card.", "Renew every year before expiry."], "steps_ar": ["استخرج الهوية أولاً.", "قدّم عبر نرعاكم أو في مركز الرعاية التابع لك مع الصورة والهوية.", "ادفع الرسم السنوي واستلم/اطبع البطاقة.", "جدّد سنوياً قبل الانتهاء."], "docs_en": ["QID", "Photo", "Sponsor documents if requested", "Vaccination card for children"], "docs_ar": ["الهوية", "صورة", "مستندات الكفيل إن طُلبت", "بطاقة التطعيم للأطفال"], "where_en": ["Nar’aakom app", "PHCC centres", "hukoomi.gov.qa"], "contacts": ["PHCC 107", "HMC 16060", "MoPH 16000"], "kw": "health card بطاقة صحية نرعاكم naraakom phcc hmc"}, {"id": "phcc-hmc", "name_en": "PHCC health centres and HMC hospitals", "name_ar": "مراكز الرعاية الأولية ومستشفيات حمد", "summary_en": "PHCC runs 27+ health centres (GP, dental, antenatal, wellness). HMC is the main public hospital network (Hamad General, Women's Wellness, Heart Hospital, Al Wakra, Al Khor, Cubes/ambulance, etc.).", "summary_ar": "تشغّل الرعاية الأولية أكثر من 27 مركزاً (عام، أسنان، حوامل، عافية). حمد هي شبكة المستشفيات الحكومية (حمد العام، صحة المرأة، القلب، الوكرة، الخور، الإسعاف وغيرها).", "steps_en": ["Register at the PHCC centre linked to your address/QID.", "Book via Nar’aakom; bring QID and health card.", "Referrals go to HMC specialties.", "Emergencies: 999 — do not wait for an appointment."], "steps_ar": ["سجّل في مركز الرعاية المرتبط بعنوانك/هويتك.", "احجز عبر نرعاكم وأحضر الهوية والبطاقة الصحية.", "التحويلات إلى تخصصات حمد.", "الطوارئ: 999 — لا تنتظر موعداً."], "docs_en": ["QID", "Health card", "Medication list"], "docs_ar": ["الهوية", "البطاقة الصحية", "قائمة الأدوية"], "where_en": ["phcc.gov.qa", "hamad.qa"], "contacts": ["107", "16060", "999"], "kw": "phcc hmc مستشفى مركز صحي موعد hamad"}, {"id": "medical-commission", "name_en": "Medical Commission (residency medical)", "name_ar": "اللجنة الطبية (فحص الإقامة)", "summary_en": "Mandatory blood tests/x-ray/clinical exam for new residency and some renewals. Unfit results delay QID.", "summary_ar": "تحاليل وصورة صدر وكشف إلزامي للإقامة الجديدة وبعض التجديدات. عدم اللياقة يؤخر البطاقة.", "steps_en": ["Sponsor books at an approved Medical Commission / authorised centre.", "Attend fasting if instructed; bring passport/visa.", "If further tests are requested, complete them promptly.", "Fit report is sent electronically to MOI."], "steps_ar": ["يحجز الكفيل في مركز لجنة طبية معتمد.", "احضر صائماً إن طُلب وأحضر الجواز/التأشيرة.", "أكمل أي فحوصات إضافية فوراً.", "يُرسل تقرير اللياقة إلكترونياً للداخلية."], "docs_en": ["Passport", "Visa", "Photos", "Vaccination evidence if asked"], "docs_ar": ["الجواز", "التأشيرة", "صور", "إثبات تطعيم إن طُلب"], "where_en": ["Medical Commission centres"], "contacts": ["16000"], "kw": "medical commission لجنة طبية فحص إقامة blood test"}, {"id": "qchp-license", "name_en": "Healthcare practitioner licence (QCHP / DHP)", "name_ar": "ترخيص مزاولة المهن الصحية", "summary_en": "Department of Healthcare Professions: Dataflow primary-source verification, Prometric/qualifying exam where required, then registration/licence.", "summary_ar": "إدارة المهن الصحية: تحقق داتافلو من المصدر، واختبار برومترك/تأهيلي عند الحاجة، ثم التسجيل/الترخيص.", "steps_en": ["Create a DHP account and submit credentials.", "Start Dataflow verification.", "Book any required Prometric or interview.", "Employer applies for the licence evaluation and issuance."], "steps_ar": ["أنشئ حساب المهن الصحية وقدّم المؤهلات.", "ابدأ تحقق داتافلو.", "احجز برومترك أو المقابلة إن لزم.", "يتقدم صاحب العمل لتقييم وإصدار الترخيص."], "docs_en": ["Degrees", "Licence from home country", "Experience letters", "Passport", "Good standing"], "docs_ar": ["الشهادات", "ترخيص بلد المصدر", "خبرات", "الجواز", "حسن سيرة"], "where_en": ["dhp.moph.gov.qa"], "contacts": ["16000"], "kw": "qchp dhp dataflow prometric رخصة طبيب تمريض"}, {"id": "health-insurance", "name_en": "Health insurance and Seha", "name_ar": "التأمين الصحي ونظام صحة", "summary_en": "Qataris use national health coverage / Seha-type schemes. Employers typically provide private insurance for expats. Mandatory insurance phases have been announced over time — confirm current MoPH status for your category.", "summary_ar": "المواطنون يستخدمون التغطية الوطنية/أنظمة من نوع صحة. أصحاب العمل عادة يؤمّنون الوافدين. أُعلنت مراحل إلزامية عبر السنوات — أكد الوضع الحالي لفئتك.", "steps_en": ["Ask HR which network (e.g. Cigna, Allianz, local insurers) you are on.", "Carry the insurance card plus QID at private hospitals.", "Public PHCC/HMC still widely used with the health card."], "steps_ar": ["اسأل الموارد البشرية عن شبكة التأمين.", "احمل بطاقة التأمين والهوية في المستشفيات الخاصة.", "الرعاية الأولية وحمد ما زالتا تُستخدمان على نطاق واسع بالبطاقة الصحية."], "docs_en": ["QID", "Insurance card", "Referral if required"], "docs_ar": ["الهوية", "بطاقة التأمين", "تحويل إن لزم"], "where_en": ["Employer", "moph.gov.qa"], "contacts": ["16000"], "kw": "insurance seha تأمين صحي صحة"}, {"id": "mental-health", "name_en": "Mental health services", "name_ar": "خدمات الصحة النفسية", "summary_en": "HMC Mental Health Service and PHCC wellness clinics. In crisis call 999. MoPH hotline 16000 can route you.", "summary_ar": "خدمات حمد للصحة النفسية وعيادات العافية بالرعاية الأولية. في الأزمة اتصل بـ 999. خط 16000 يوجّهك.", "steps_en": ["Book GP at PHCC and request referral", "Or attend HMC mental health emergency pathways", "Private psychiatry is also available with insurance"], "steps_ar": ["احجز طبيباً عاماً واطلب تحويلاً", "أو استخدم مسار طوارئ الصحة النفسية بحمد", "العيادات الخاصة متاحة مع التأمين"], "docs_en": ["QID", "Health card / insurance"], "docs_ar": ["الهوية", "البطاقة الصحية / التأمين"], "where_en": ["HMC Mental Health Hospital", "PHCC"], "contacts": ["999", "16000", "16060"], "kw": "mental health نفسي اكتئاب أزمة"}, {"id": "birth-death", "name_en": "Birth and death registration", "name_ar": "تسجيل المواليد والوفيات", "summary_en": "Hospital notifies; civil registration / certificates via official civil status channels (ADLSA / competent authority). Newborns need residency/QID sponsorship next.", "summary_ar": "المستشفى يبلّغ؛ التسجيل المدني والشهادات عبر القنوات الرسمية. المولود يحتاج كفالة إقامة/هوية بعد ذلك.", "steps_en": ["Obtain the hospital birth notification.", "Register the birth and collect the official certificate.", "Apply for the baby’s residency on Metrash under a parent’s sponsorship."], "steps_ar": ["احصل على إشعار الولادة من المستشفى.", "سجّل الولادة واستخرج الشهادة الرسمية.", "قدّم إقامة المولود على مترآش تحت كفالة أحد الوالدين."], "docs_en": ["Parents’ QIDs and marriage certificate", "Hospital notification", "Passports"], "docs_ar": ["هويات الوالدين وعقد الزواج", "إشعار المستشفى", "الجوازات"], "where_en": ["Hospital", "Civil registry", "Metrash"], "contacts": ["109"], "kw": "birth death مولود وفاة شهادة ميلاد"}, {"id": "school-enrol", "name_en": "School enrolment and transfer", "name_ar": "التسجيل في المدارس والتحويل", "summary_en": "Public schools: ministry windows for eligible students. Private/international: apply school-by-school. Transfers from abroad need attested reports.", "summary_ar": "الحكومية: نوافذ الوزارة للطلاب المؤهلين. الخاصة/الدولية: تقديم لكل مدرسة. التحويل من الخارج يحتاج كشوف مصدّقة.", "steps_en": ["Decide public vs private and curriculum (Qatari, British, IB, American, Indian, etc.).", "Watch MOEHE announcements for government enrolment dates.", "For private schools: entrance test, seat offer, fee payment.", "Attest last school reports via origin country, Qatar Embassy, and MOFA if required."], "steps_ar": ["حدد حكومي أو خاص والمنهج.", "تابع إعلانات الوزارة لمواعيد التسجيل الحكومي.", "للخاص: اختبار قبول وعرض مقعد ودفع الرسوم.", "صدّق آخر الكشوف من بلد المصدر وسفارة قطر والخارجية إن لزم."], "docs_en": ["Child passport & QID", "Vaccination", "Last 2 years reports", "Photos", "Parent QID"], "docs_ar": ["جواز الطفل وهويته", "التطعيم", "كشوف سنتين", "صور", "هوية ولي الأمر"], "where_en": ["edu.gov.qa", "school portals"], "contacts": ["MOEHE via Hukoomi 109"], "kw": "school مدرسة تسجيل تحويل enrollment"}, {"id": "universities", "name_en": "Universities and Education City", "name_ar": "الجامعات والمدينة التعليمية", "summary_en": "Qatar University, Community College of Qatar, and Education City branches: Georgetown, Northwestern, Carnegie Mellon, Texas A&M, Weill Cornell, VCU, HEC Paris, plus HBKU.", "summary_ar": "جامعة قطر وكلية المجتمع وفروع المدينة التعليمية: جورجتاون، نورثويسترن، كارنيجي ميلون، تكساس إيه آند إم، وايل كورنيل، فيرجينيا كومنولث، إتش إي سي باريس، إضافة إلى جامعة حمد بن خليفة.", "steps_en": ["Check each university’s admissions portal and deadlines.", "Prepare transcripts, standardised tests, and English scores as required.", "Qatari students may apply for government scholarships via MOEHE."], "steps_ar": ["راجع بوابة القبول والمواعيد لكل جامعة.", "جهّز السجلات والاختبارات ودرجات اللغة.", "يمكن للطلاب القطريين التقديم لمنح الوزارة."], "docs_en": ["High-school diploma + equivalency", "Passport/QID", "Test scores", "Personal statement"], "docs_ar": ["شهادة الثانوية + المعادلة", "الجواز/الهوية", "درجات الاختبارات", "خطاب شخصي"], "where_en": ["qu.edu.qa", "qf.org.qa"], "contacts": ["109"], "kw": "university جامعة قطر education city منحة"}, {"id": "equivalency", "name_en": "Certificate equivalency and attestation", "name_ar": "معادلة الشهادات والتصديق", "summary_en": "Foreign school/university certificates often need MOFA attestation and MOEHE equivalency for study, teacher licensing, or some jobs.", "summary_ar": "شهادات الخارج غالباً تحتاج تصديق الخارجية ومعادلة الوزارة للدراسة أو ترخيص المعلمين أو بعض الوظائف.", "steps_en": ["Attest documents in the issuing country.", "Attest at the Qatar embassy then Qatar MOFA.", "Submit equivalency on the ministry’s electronic system."], "steps_ar": ["صدّق المستندات في بلد الإصدار.", "صدّق في سفارة قطر ثم الخارجية القطرية.", "قدّم المعادلة على نظام الوزارة الإلكتروني."], "docs_en": ["Original certificates", "Transcripts", "Passport", "Translations"], "docs_ar": ["أصول الشهادات", "كشوف الدرجات", "الجواز", "ترجمات"], "where_en": ["MOEHE", "MOFA attestation"], "contacts": ["109"], "kw": "equivalency معادلة تصديق شهادة"}, {"id": "building-permit", "name_en": "Building permits and land-use", "name_ar": "رخص البناء واستخدامات الأراضي", "summary_en": "Municipality + Ashghal coordination. Zoning, setbacks, and engineering drawings required. Civil Defence for many occupancies.", "summary_ar": "تنسيق البلدية وأشغال. يلزم التقسيم والارتدادات والمخططات الهندسية. الدفاع المدني لكثير من الإشغالات.", "steps_en": ["Confirm zoning and plot data.", "Hire a registered engineering office.", "Submit drawings and pay scrutiny fees.", "Obtain permit before any construction; request inspections and completion certificate."], "steps_ar": ["أكد بيانات التقسيم والقسيمة.", "عيّن مكتباً هندسياً مسجلاً.", "قدّم المخططات وادفع رسوم المراجعة.", "استخرج الرخصة قبل أي بناء واطلب الكشف وشهادة الإنجاز."], "docs_en": ["Title deed", "Survey", "Full drawings", "Owner QID", "Contractor licence"], "docs_ar": ["سند الملكية", "المساحة", "المخططات", "هوية المالك", "رخصة المقاول"], "where_en": ["Ministry of Municipality digital services", "Baladiya app"], "contacts": ["184", "Ashghal 188"], "kw": "building permit رخصة بناء أشغال بلدية zoning"}, {"id": "food-licence", "name_en": "Food establishment licence", "name_ar": "رخصة المنشآت الغذائية", "summary_en": "CR + municipal food licence + Civil Defence + food-handler certificates + inspections.", "summary_ar": "سجل تجاري + رخصة غذاء بلدية + دفاع مدني + شهادات مناولة + تفتيش.", "steps_en": ["Add food activity on CR.", "Fit-out to food-hygiene specs.", "Apply for municipal licence and book inspection.", "Train staff (food safety) and keep logs."], "steps_ar": ["أضف نشاط الغذاء على السجل.", "جهّز الموقع وفق اشتراطات النظافة.", "قدّم للرخصة البلدية واحجز الكشف.", "درّب العاملين واحتفظ بالسجلات."], "docs_en": ["CR", "Lease/fit-out drawings", "Civil Defence", "Manager QID", "Menu"], "docs_ar": ["السجل", "الإيجار/مخططات", "الدفاع المدني", "هوية المدير", "قائمة الطعام"], "where_en": ["Baladiya / Municipality"], "contacts": ["184"], "kw": "restaurant food licence مطعم رخصة غذاء"}, {"id": "baladiya-complaints", "name_en": "Municipality complaints and Makani address", "name_ar": "شكاوى البلدية وعنوان مكاني", "summary_en": "Report waste, pests, violations via Baladiya app. Makani is Qatar’s national address code used for delivery and emergencies.", "summary_ar": "بلّغ عن النفايات والآفات والمخالفات عبر تطبيق بلدية. مكاني هو نظام العنوان الوطني للتوصيل والطوارئ.", "steps_en": ["Install Baladiya and pin the location or enter Makani.", "Upload photos and description.", "Track the ticket number."], "steps_ar": ["ثبّت بلدية وحدّد الموقع أو أدخل مكاني.", "ارفع صوراً ووصفاً.", "تتبع رقم البلاغ."], "docs_en": ["Photos", "Makani / PIN"], "docs_ar": ["صور", "مكاني / الموقع"], "where_en": ["Baladiya app", "184"], "contacts": ["184"], "kw": "baladiya مكاني makani شكوى نظافة حشرات"}, {"id": "courts", "name_en": "Court system and Adala / Taqadi", "name_ar": "النظام القضائي وعدالة / تقاضي", "summary_en": "Court of First Instance, Court of Appeal, Court of Cassation. Track cases on official judiciary portals (Adala / Taqadi).", "summary_ar": "المحكمة الابتدائية ثم الاستئناف ثم التمييز. تتبع القضايا عبر البوابات الرسمية (عدالة / تقاضي).", "steps_en": ["Consult a licensed lawyer for filings.", "File at the competent court registry or e-platform.", "Attend hearings (some remote).", "Appeal within statutory deadlines."], "steps_ar": ["استشر محامياً مرخصاً.", "أودع الدعوى في القلم المختص أو المنصة.", "احضر الجلسات (بعضها عن بُعد).", "استأنف ضمن المواعيد النظامية."], "docs_en": ["QID", "POA", "Evidence", "Translations"], "docs_ar": ["الهوية", "توكيل", "أدلة", "ترجمات"], "where_en": ["Supreme Judiciary Council portals"], "contacts": ["Hukoomi 109"], "kw": "court محكمة عدالة تقاضي استئناف تمييز"}, {"id": "family-law", "name_en": "Marriage, divorce, custody", "name_ar": "الزواج والطلاق والحضانة", "summary_en": "Muslim marriages typically registered through official Sharia/family procedures. Mixed-nationality marriages have extra documentation. Divorce and custody are court matters — get licensed advice.", "summary_ar": "زواج المسلمين يُوثَّق عبر الإجراءات الشرعية/الأسرية الرسمية. الزواج المختلط يحتاج مستندات إضافية. الطلاق والحضانة أمام المحكمة — استشر مختصاً مرخصاً.", "steps_en": ["Gather IDs, proof of religion/status, and any embassy papers.", "Book the competent documentation authority / court.", "For divorce/custody, file a family case; mediation may be offered."], "steps_ar": ["جهّز الهويات وإثبات الحالة وأي أوراق سفارات.", "احجز جهة التوثيق/المحكمة المختصة.", "للطلاق/الحضانة ارفع دعوى أسرية وقد تُعرض الوساطة."], "docs_en": ["Passports/QIDs", "Pre-marital medicals if required", "Guardian/embassy letters"], "docs_ar": ["الجوازات/الهويات", "فحوصات ما قبل الزواج إن لزم", "خطابات الولي/السفارة"], "where_en": ["Family courts", "documentation authorities"], "contacts": ["109"], "kw": "marriage divorce حضانة زواج طلاق family"}, {"id": "notary", "name_en": "Notary, POA, and attestation", "name_ar": "التوثيق والوكالات والتصديق", "summary_en": "Ministry of Justice notaries authenticate contracts, powers of attorney, and declarations. Bring two parties and translators if needed.", "summary_ar": "كتاب العدل بوزارة العدل يوثقون العقود والوكالات والإقرارات. أحضر الطرفين ومترجماً إن لزم.", "steps_en": ["Book a notary appointment on MOJ digital services.", "Draft the POA in Arabic (legal language).", "Sign before the notary with QIDs."], "steps_ar": ["احجز موعد توثيق عبر خدمات العدل الرقمية.", "صغ الوكالة بالعربية القانونية.", "وقّع أمام كاتب العدل بالهويات."], "docs_en": ["QID/passport", "Draft text", "Company CR if corporate"], "docs_ar": ["الهوية/الجواز", "مسودة النص", "سجل الشركة إن كانت طرفاً"], "where_en": ["MOJ notary offices"], "contacts": ["109"], "kw": "notary وكالة توكيل توثيق poa"}, {"id": "foreign-property", "name_en": "Property purchase by non-Qataris", "name_ar": "شراء العقار لغير القطريين", "summary_en": "Allowed in designated zones (The Pearl, Lusail, West Bay Lagoon, announced Al Khor and other projects). Freehold or long usufruct (often 99 years). Registration fee commonly ~0.25% of value.", "summary_ar": "مسموح في مناطق محددة (اللؤلؤة، لوسيل، غرب الخليج، ومشاريع معلنة بالخور وغيرها). تملك حر أو انتفاع طويل (غالباً 99 سنة). رسم التسجيل الشائع نحو 0.25% من القيمة.", "steps_en": ["Confirm the unit is in a designated foreign-ownership area.", "Sign SPA with the developer/seller; pay deposits per contract.", "Register transfer with the real-estate registration authority.", "Ask MOI about residency-by-property products if you need that pathway."], "steps_ar": ["تأكد أن الوحدة في منطقة تملك أجنبي معلنة.", "وقّع عقد البيع مع المطوّر/البائع وادفع العربون وفق العقد.", "سجّل النقل لدى جهة التسجيل العقاري.", "اسأل الداخلية عن منتجات الإقامة المرتبطة بالعقار إن رغبت."], "docs_en": ["Passport/QID", "SPA", "NOCs", "Payment proofs"], "docs_ar": ["الجواز/الهوية", "عقد البيع", "الموافقات", "إثباتات الدفع"], "where_en": ["Real estate registration", "developers"], "contacts": ["109"], "kw": "property buy pearl lusail عقار تملك أجنبي بيت شراء بيت منزل غير قطري foreigner buy house apartment"}, {"id": "bank-account", "name_en": "Opening a bank account", "name_ar": "فتح حساب بنكي", "summary_en": "Banks require QID (or arrival pack for some salary accounts), mobile number, and often salary letter / employer NOC. Islamic and conventional options exist (QNB, QIB, CBQ, Doha Bank, Dukhan, etc.).", "summary_ar": "البنوك تطلب الهوية (أو حزمة الوصول لبعض حسابات الراتب) ورقم الجوال وغالباً خطاب راتب/عدم ممانعة. تتوفر خيارات إسلامية وتقليدية.", "steps_en": ["Compare banks for WPS salary and fees.", "Book a branch appointment with QID, passport, and salary certificate.", "Complete KYC and collect debit card / IBAN."], "steps_ar": ["قارن البنوك من حيث حماية الأجور والرسوم.", "احجز فرعاً بالهوية والجواز وشهادة الراتب.", "أكمل اعرف عميلك واستلم البطاقة والآيبان."], "docs_en": ["QID", "Passport", "Salary certificate", "Employer letter", "Proof of address if asked"], "docs_ar": ["الهوية", "الجواز", "شهادة راتب", "خطاب جهة العمل", "إثبات عنوان إن طُلب"], "where_en": ["Licensed banks"], "contacts": ["QCB consumer channels via qcb.gov.qa"], "kw": "bank حساب بنكي iban qnb islamic"}, {"id": "tax", "name_en": "Taxation, excise, and zakat", "name_ar": "الضرائب والانتقائية والزكاة", "summary_en": "No personal income tax on salaries. Corporate tax generally 10% on foreign taxable profits. Excise on tobacco, energy drinks, carbonated/sugary drinks. No VAT currently. Zakat Fund: mandatory framework for eligible Qatari companies; voluntary for individuals.", "summary_ar": "لا ضريبة دخل على الرواتب. ضريبة الشركات عموماً 10% على أرباح الأجانب الخاضعة. انتقائية على التبغ ومشروبات الطاقة والمحلاة. لا ضريبة قيمة مضافة حالياً. صندوق الزكاة: إطار إلزامي للشركات القطرية المستحقة وتطوعي للأفراد.", "steps_en": ["Register with the General Tax Authority within the statutory period after incorporation.", "File corporate returns annually if in scope.", "Excise registrants file per GTA calendar."], "steps_ar": ["سجّل لدى الهيئة العامة للضرائب خلال المهلة بعد التأسيس.", "قدّم الإقرارات السنوية إن كنت مشمولاً.", "مسجّلو الانتقائية يلتزمون بجدول الهيئة."], "docs_en": ["CR", "Financials", "TIN application"], "docs_ar": ["السجل", "القوائم المالية", "طلب الرقم الضريبي"], "where_en": ["gta.gov.qa", "zakat fund"], "contacts": ["GTA via Hukoomi 109"], "kw": "tax vat ضريبة زكاة excise 10%"}, {"id": "vehicle-insurance", "name_en": "Mandatory vehicle insurance", "name_ar": "تأمين المركبات الإلزامي", "summary_en": "Third-party motor insurance is mandatory to register/renew a vehicle. Comprehensive is optional but common for financed cars.", "summary_ar": "تأمين المسؤولية تجاه الغير إلزامي للتسجيل/التجديد. الشامل اختياري وشائع للسيارات الممولة.", "steps_en": ["Compare licensed insurers", "Buy policy with istimara data", "Upload to Metrash renewal"], "steps_ar": ["قارن شركات مرخصة", "اشترِ الوثيقة ببيانات الاستمارة", "ارفعها مع تجديد مترآش"], "docs_en": ["QID", "Istimara", "Previous policy"], "docs_ar": ["الهوية", "الاستمارة", "الوثيقة السابقة"], "where_en": ["Licensed insurers"], "contacts": ["109"], "kw": "insurance سيارة تأمين إلزامي"}, {"id": "kahramaa", "name_en": "Kahramaa electricity and water", "name_ar": "كهرماء للكهرباء والماء", "summary_en": "Apply for connection/transfer with QID and tenancy. Tariffs differ for Qatari households vs others and commercial. Emergency 991.", "summary_ar": "قدّم للتوصيل/النقل بالهوية وعقد الإيجار. التعرفة تختلف للمواطنين وغيرهم والتجاري. الطوارئ 991.", "steps_en": ["Create a Kahramaa account (app/web).", "Submit tenancy or title and previous-occupant clearance if any.", "Pay deposit and connection charges.", "Read the meter number on every bill; set auto-pay."], "steps_ar": ["أنشئ حساب كهرماء (تطبيق/موقع).", "قدّم الإيجار أو الملكية ومخالصة الشاغل السابق إن وُجدت.", "ادفع التأمين ورسوم التوصيل.", "اقرأ رقم العداد في كل فاتورة وفعّل الدفع التلقائي."], "docs_en": ["QID", "Tenancy/title", "Previous bill if transfer"], "docs_ar": ["الهوية", "إيجار/ملكية", "فاتورة سابقة إن وُجدت"], "where_en": ["km.qa", "Kahramaa app"], "contacts": ["991"], "kw": "kahramaa كهرماء كهرباء ماء فاتورة"}, {"id": "telecom", "name_en": "Ooredoo and Vodafone Qatar SIMs", "name_ar": "شرائح أوريدو وفودافون قطر", "summary_en": "Prepaid or postpaid requires QID (visitors use passport). One person can register a limited number of SIMs. eSIM available.", "summary_ar": "المسبقة أو الآجلة تحتاج هوية (الزائر بالجواز). حد لعدد الشرائح للشخص. تتوفر الشريحة الإلكترونية.", "steps_en": ["Visit a branded store with QID.", "Choose prepaid tourist, prepaid resident, or postpaid salary plan.", "Complete biometric/SIM registration (legal requirement)."], "steps_ar": ["زر فرعاً رسمياً بالهوية.", "اختر مسبقة للزائر أو المقيم أو آجلة على الراتب.", "أكمل تسجيل الشريحة البيومتري (متطلب قانوني)."], "docs_en": ["QID or passport", "IBAN for postpaid"], "docs_ar": ["الهوية أو الجواز", "آيبان للآجل"], "where_en": ["ooredoo.qa", "vodafone.qa"], "contacts": ["111"], "kw": "ooredoo vodafone شريحة جوال نت"}, {"id": "qatar-post", "name_en": "Qatar Post and PO Box", "name_ar": "بريد قطر والصندوق البريدي", "summary_en": "PO boxes, parcel delivery, and QID/licence home delivery. Directory 104.", "summary_ar": "صناديق بريد وطرود وتوصيل الهوية/الرخص. الدليل 104.", "steps_en": ["Apply for a PO Box with QID/CR", "Pay annual rental", "Collect mail or enable delivery notifications"], "steps_ar": ["قدّم لصندوق بالهوية/السجل", "ادفع الإيجار السنوي", "استلم البريد أو فعّل التنبيهات"], "docs_en": ["QID or CR"], "docs_ar": ["الهوية أو السجل"], "where_en": ["qatarpost.qa"], "contacts": ["104"], "kw": "post po box بريد طرد"}, {"id": "doha-metro", "name_en": "Doha Metro (Qatar Rail)", "name_ar": "مترو الدوحة (قطر ريل)", "summary_en": "Red, Green, and Gold lines. Standard fare typically QAR 2; Gold Club about QAR 10. Travel cards at stations. Hotline 105.", "summary_ar": "الخطوط الأحمر والأخضر والذهبي. الأجرة العادية عادة ريالان ونادي الذهب نحو 10 ريالات. بطاقات في المحطات. 105.", "steps_en": ["Buy a standard or Gold travel card / use the official app.", "Tap in and out; keep the card topped up.", "Check last-train times (often around midnight)."], "steps_ar": ["اشترِ بطاقة عادية أو ذهبية / استخدم التطبيق الرسمي.", "مرّر عند الدخول والخروج واشحن الرصيد.", "راجع مواعيد آخر قطار (غالباً نحو منتصف الليل)."], "docs_en": ["QID helpful for registered cards"], "docs_ar": ["الهوية مفيدة للبطاقات المسجّلة"], "where_en": ["qatarrail.com", "stations"], "contacts": ["105"], "kw": "metro مترو دوحة red green gold qatar rail"}, {"id": "karwa", "name_en": "Karwa bus and taxi (Mowasalat)", "name_ar": "حافلات تاكسي كروة (مواصلات)", "summary_en": "Public buses across Doha; taxis via 44588888, Karwa Taxi app, or ranks (airport, malls, metro). Metered fares; airport surcharge may apply.", "summary_ar": "حافلات عامة في الدوحة؛ التاكسي عبر 44588888 أو التطبيق أو المواقف. أجرة بعداد وقد تُضاف زيادة المطار.", "steps_en": ["Use Karwa smart card on buses", "Book taxi in the official app", "Complain via Mowasalat if needed"], "steps_ar": ["استخدم بطاقة كروة في الحافلات", "احجز التاكسي من التطبيق الرسمي", "قدّم شكوى عبر مواصلات إن لزم"], "docs_en": [], "docs_ar": [], "where_en": ["mowasalat.com"], "contacts": ["44588888", "Transport 16016"], "kw": "karwa كروة تاكسي باص مواصلات"}, {"id": "hia", "name_en": "Hamad International Airport", "name_ar": "مطار حمد الدولي", "summary_en": "Main gateway. Visa on arrival / Hayya as eligible. Duty-free allowances apply. Declare restricted goods. Airport 40106666.", "summary_ar": "البوابة الرئيسية. تأشيرة عند الوصول / هيا حسب الأهلية. بدلات السوق الحرة سارية. صرّح عن البضائع المقيدة. 40106666.", "steps_en": ["Check visa/Hayya before flying.", "Complete any electronic health/customs declarations in force.", "Keep prohibited items (certain medicines, drones, etc.) off your bags unless permitted."], "steps_ar": ["تحقق من التأشيرة/هيا قبل الإقلاع.", "أكمل أي إقرارات صحية/جمركية سارية.", "لا تحمل ممنوعات (بعض الأدوية، درونز وغيرها) دون تصريح."], "docs_en": ["Passport", "Visa/Hayya", "Return ticket"], "docs_ar": ["الجواز", "التأشيرة/هيا", "تذكرة العودة"], "where_en": ["dohahamadairport.com"], "contacts": ["40106666"], "kw": "airport حمد مطار hayya duty free جمارك"}, {"id": "vehicle-import", "name_en": "Importing a vehicle", "name_ar": "استيراد مركبة", "summary_en": "Age limits, GCC specs, customs duty, and Fahes apply. Register with MOI after clearance.", "summary_ar": "تسري حدود العمر ومواصفات الخليج والجمارك وفاحص. سجّل لدى الداخلية بعد الإفراج.", "steps_en": ["Confirm the car meets Qatar/GCC import age and spec rules.", "Ship to Hamad Port / authorised entry; pay customs.", "Pass Fahes and insure, then register plates."], "steps_ar": ["تأكد من عمر ومواصفات الاستيراد.", "اشحن عبر الميناء وادفع الجمارك.", "اجتز فاحص وأمّن ثم استخرج اللوحات."], "docs_en": ["Export title", "Bill of lading", "QID", "Invoice"], "docs_ar": ["ملكية التصدير", "بوليصة الشحن", "الهوية", "الفاتورة"], "where_en": ["Customs", "Fahes", "Traffic"], "contacts": ["109"], "kw": "import car استيراد سيارة جمارك"}, {"id": "rental-law", "name_en": "Rental law and tenancy disputes", "name_ar": "قانون الإيجار ومنازعاته", "summary_en": "Use a written registered contract. Rent increases and eviction are regulated. Disputes go to the Rental Disputes Settlement Committee — not the police.", "summary_ar": "استخدم عقداً مكتوباً مسجلاً. زيادة الإيجار والإخلاء منظّمان. النزاعات أمام لجنة فض المنازعات الإيجارية وليس الشرطة.", "steps_en": ["Sign a bilingual contract stating rent, deposit, and duration.", "Register the tenancy on the official platform in use.", "Pay via bank transfer and keep receipts.", "For disputes, file at the Rental Committee with the contract and evidence."], "steps_ar": ["وقّع عقداً باللغتين يحدد الإيجار والتأمين والمدة.", "سجّل العقد على المنصة الرسمية المعتمدة.", "ادفع تحويلاً بنكياً واحفظ الإيصالات.", "للنزاع ارفع ملفك للجنة الإيجارات مع العقد والأدلة."], "docs_en": ["Contract", "QIDs", "Payment proofs", "Photos of property"], "docs_ar": ["العقد", "الهويات", "إثباتات الدفع", "صور العقار"], "where_en": ["Rental Disputes Committee"], "contacts": ["109"], "kw": "rent إيجار عقد إخلاء لجنة"}, {"id": "gov-housing", "name_en": "Government housing and loans for Qataris", "name_ar": "الإسكان الحكومي وقروض المواطنين", "summary_en": "Qatari nationals may access government housing programmes and MADLSA / housing-loan products subject to eligibility (marital status, income, not already owning adequate housing).", "summary_ar": "يمكن للمواطنين الاستفادة من برامج الإسكان الحكومي ومنتجات القروض عبر التنمية الاجتماعية/الإسكان وفق الأهلية (الحالة الاجتماعية والدخل وعدم تملك مسكن كافٍ).", "steps_en": ["Check current eligibility on the competent ministry portal.", "Submit family documents and income evidence.", "Await allocation or loan decision; comply with building timelines."], "steps_ar": ["تحقق من الأهلية الحالية على بوابة الجهة المختصة.", "قدّم مستندات الأسرة والدخل.", "انتظر قرار التخصيص أو القرض والتزم بجداول البناء."], "docs_en": ["Qatari IDs", "Marriage certificate", "Salary", "Deed search"], "docs_ar": ["الهويات القطرية", "عقد الزواج", "الراتب", "كشف أملاك"], "where_en": ["Social Development / housing portals"], "contacts": ["109"], "kw": "government housing إسكان مواطنين قرض"}, {"id": "social-security", "name_en": "Social security, pensions, disability support", "name_ar": "الضمان الاجتماعي والمعاشات ودعم الإعاقة", "summary_en": "Primarily for Qatari nationals through the Ministry of Social Development and Family and related funds. Includes disability services and family assistance.", "summary_ar": "أساساً للمواطنين عبر وزارة التنمية الاجتماعية والأسرة والصناديق المرتبطة. يشمل خدمات الإعاقة والمساعدات الأسرية.", "steps_en": ["Confirm Qatari eligibility and programme type.", "Apply on the ministry’s digital services with civil documents.", "Attend assessment appointments for disability benefits."], "steps_ar": ["أكد أهلية المواطن ونوع البرنامج.", "قدّم عبر الخدمات الرقمية بالمستندات المدنية.", "احضر تقييم الإعاقة إن لزم."], "docs_en": ["Qatari IDs", "Medical reports", "IBAN", "Family book"], "docs_ar": ["الهويات القطرية", "تقارير طبية", "آيبان", "دفتر العائلة"], "where_en": ["msdf.gov.qa"], "contacts": ["109"], "kw": "social security ضمان معاش إعاقة"}, {"id": "domestic-workers", "name_en": "Domestic workers’ contracts and rights", "name_ar": "عقود وحقوق العمالة المنزلية", "summary_en": "Law No. 15 of 2017: written contract, wage, rest, annual leave, end-of-service (min. 3 weeks/year after 1 year), decent accommodation. Disputes via MOL / specialised committees.", "summary_ar": "القانون 15 لسنة 2017: عقد مكتوب وأجر وراحة وإجازة سنوية ومكافأة (3 أسابيع/سنة بعد سنة) وسكن لائق. النزاعات عبر العمل/اللجان المختصة.", "steps_en": ["Use the official domestic-worker contract template.", "Pay wages via documented channels.", "Either party may complain to MOL if terms are breached."], "steps_ar": ["استخدم نموذج عقد العمالة المنزلية الرسمي.", "ادفع الأجر عبر قنوات موثقة.", "يجوز لأي طرف الشكوى لوزارة العمل عند الإخلال."], "docs_en": ["Contract", "QID", "Passport", "Wage evidence"], "docs_ar": ["العقد", "الهوية", "الجواز", "إثبات الأجر"], "where_en": ["MOL domestic labour services"], "contacts": ["16505"], "kw": "domestic maid عاملة منزلية حقوق عقد"}, {"id": "ngo", "name_en": "Associations and NGO registration", "name_ar": "تسجيل الجمعيات والمنظمات", "summary_en": "Private associations and foundations are licensed under Qatari law via the competent social-development authority. Foreign NGOs need special approval.", "summary_ar": "تُرخَّص الجمعيات والمؤسسات الخاصة وفق القانون عبر جهة التنمية الاجتماعية المختصة. المنظمات الأجنبية تحتاج موافقة خاصة.", "steps_en": ["Prepare founding members’ QIDs and bylaws in Arabic.", "Submit to the competent department and await security/administrative review.", "After licence, keep governance, accounts, and activity reports."], "steps_ar": ["جهّز هويات المؤسسين والنظام الأساسي بالعربية.", "قدّم للإدارة المختصة وانتظر المراجعة.", "بعد الترخيص التزم بالحوكمة والحسابات والتقارير."], "docs_en": ["Bylaws", "Founders’ IDs", "Premises", "Programme description"], "docs_ar": ["النظام الأساسي", "هويات المؤسسين", "المقر", "وصف البرامج"], "where_en": ["MSDF"], "contacts": ["109"], "kw": "ngo جمعية مؤسسة مجتمع مدني"}, {"id": "emergency", "name_en": "Emergency and government hotlines", "name_ar": "أرقام الطوارئ والخطوط الحكومية", "summary_en": "999 police/fire/ambulance; 991 Kahramaa; 16000 health; 107 PHCC; 16060 HMC; 109 Hukoomi; 16505 labour; 184 municipality; 105 metro; 111 telecom.", "summary_ar": "999 شرطة/إطفاء/إسعاف؛ 991 كهرماء؛ 16000 صحة؛ 107 رعاية أولية؛ 16060 حمد؛ 109 حكومي؛ 16505 عمل؛ 184 بلدية؛ 105 مترو؛ 111 اتصالات.", "steps_en": ["Life-threatening: 999 immediately. Share Makani if you can.", "Utility outage/leak: 991.", "Non-urgent government questions: 109."], "steps_ar": ["خطر على الحياة: 999 فوراً. أرسل مكاني إن استطعت.", "عطل/تسرب مرافق: 991.", "استفسارات حكومية غير عاجلة: 109."], "docs_en": [], "docs_ar": [], "where_en": ["Any phone"], "contacts": ["999", "109"], "kw": "emergency 999 طوارئ hotline 109 991"}, {"id": "family-sponsorship", "name_en": "Family sponsorship (wife and children residence)", "name_ar": "استقدام الأسرة (إقامة الزوجة والأبناء)", "summary_en": "A resident sponsor applies on Metrash for family residence visas. Employers and MOI apply income/housing conditions that change — confirm the live salary threshold on MOI/Metrash (commonly discussed figures have been in the QAR 10,000 range for some categories; do not treat that as law). Marriage certificate and children's birth certificates must be attested.", "summary_ar": "يتقدم المقيم الكفيل عبر مترآش لإقامة الزوجة والأبناء. تشترط الداخلية/جهة العمل شروط دخل وسكن تتغير — أكد حد الراتب الحي على مترآش (أرقام شائعة نوقشت حول 10,000 ريال لبعض الفئات وليست نص قانون ثابت). يلزم تصديق عقد الزواج وشهادات الميلاد.", "steps_en": ["Confirm your employer allows family sponsorship and your contract/salary meets the current MOI rule.", "Attest marriage and birth certificates (origin country → Qatar embassy → Qatar MOFA).", "Apply on official Metrash for each dependent.", "After arrival: medical, biometrics, QID, health card.", "School and bank accounts follow once QIDs are issued."], "steps_ar": ["تأكد أن جهة العمل تسمح باستقدام الأسرة وأن الراتب يطابق قاعدة الداخلية الحالية.", "صدّق عقد الزواج وشهادات الميلاد (بلد المصدر ← سفارة قطر ← الخارجية).", "قدّم لكل تابع عبر مترآش الرسمي.", "بعد الوصول: الفحص الطبي والبصمة والهوية والبطاقة الصحية.", "المدرسة والحساب البنكي بعد صدور الهويات."], "docs_en": ["Sponsor QID", "Salary certificate", "Attested marriage certificate", "Attested birth certificates", "Passports", "Housing proof"], "docs_ar": ["هوية الكفيل", "شهادة راتب", "عقد زواج مصدّق", "شهادات ميلاد مصدّقة", "الجوازات", "إثبات سكن"], "where_en": ["Metrash", "MOI portal"], "contacts": ["MOI 2366666"], "kw": "family sponsorship استقدام أسرة زوجة أبناء wife children dependents salary"}, {"id": "hayya-tourist", "name_en": "Hayya tourist / visit entry", "name_ar": "هيا للسياحة والزيارة", "summary_en": "hayya.qa is the official channel for many tourist and event entry permits. Eligibility depends on nationality and package. Not the same as a family residence visa.", "summary_ar": "hayya.qa القناة الرسمية لكثير من تصاريح السياحة والفعاليات. الأهلية حسب الجنسية والباقة. ليست إقامة عائلية.", "steps_en": ["Create an account on hayya.qa.", "Choose the product that matches your nationality and trip.", "Upload passport and photo; pay if required.", "Save the Hayya/visa and check airline conditions.", "Do not overstay."], "steps_ar": ["أنشئ حساباً على hayya.qa.", "اختر المنتج المناسب لجنسيتك ورحلتك.", "ارفع الجواز والصورة وادفع إن لزم.", "احفظ هيا/التأشيرة وراجع شروط الخطوط.", "لا تتجاوز المدة."], "docs_en": ["Passport 6+ months", "Photo", "Return plan"], "docs_ar": ["جواز 6 أشهر+", "صورة", "خطة عودة"], "where_en": ["hayya.qa"], "contacts": ["Hukoomi 109"], "kw": "hayya هيا سياحة tourist visit entry"}, {"id": "black-points", "name_en": "Traffic black points and licence suspension", "name_ar": "النقاط السوداء وإيقاف الرخصة", "summary_en": "Traffic violations add black points viewed on Metrash. Accumulating the legal maximum can suspend the licence. Some fines are discounted if paid within 30 days — confirm on Metrash.", "summary_ar": "المخالفات تضيف نقاطاً سوداء تظهر على مترآش. بلوغ الحد القانوني قد يوقف الرخصة. بعض الغرامات تُخفض إن دُفعت خلال 30 يوماً — أكد على مترآش.", "steps_en": ["Open Metrash → Traffic → violations and black points.", "Pay fines by card; save the receipt.", "If the licence is blocked, follow the Traffic Department instructions."], "steps_ar": ["افتح مترآش ← المرور ← المخالفات والنقاط.", "ادفع بالبطاقة واحفظ الإيصال.", "إذا أُوقفت الرخصة اتبع تعليمات المرور."], "docs_en": ["QID", "Licence"], "docs_ar": ["الهوية", "الرخصة"], "where_en": ["Metrash", "MOI portal"], "contacts": ["MOI 2366666"], "kw": "black points نقاط سوداء مخالفة غرامة traffic fine suspension"}, {"id": "sim-registration", "name_en": "Mandatory SIM registration (Ooredoo / Vodafone)", "name_ar": "تسجيل الشريحة الإلزامي (أوريدو / فودافون)", "summary_en": "Every Qatari mobile number must be registered to a QID (or passport for visitors). Unregistered SIMs are cut. One person may hold only a limited number of lines.", "summary_ar": "كل رقم قطري يجب أن يُسجَّل على هوية (أو جواز للزائر). الشريحة غير المسجّلة تُقطع. يوجد حد لعدد الخطوط للشخص.", "steps_en": ["Visit an official Ooredoo or Vodafone store with QID.", "Complete biometric / e-KYC registration.", "Keep the SIM in your name — do not buy unregistered street SIMs."], "steps_ar": ["زر فرعاً رسمياً لأوريدو أو فودافون بالهوية.", "أكمل التسجيل البيومتري.", "أبقِ الشريحة باسمك — لا تشترِ شرائح غير مسجّلة."], "docs_en": ["QID or visitor passport"], "docs_ar": ["الهوية أو جواز الزائر"], "where_en": ["ooredoo.qa", "vodafone.qa"], "contacts": ["111"], "kw": "sim شريحة تسجيل ooredoo vodafone mandatory"}, {"id": "gov-hours", "name_en": "Government office working hours", "name_ar": "أوقات عمل الدوائر الحكومية", "summary_en": "Most Qatar government service centres operate Sunday–Thursday, typically 07:00–14:00. Some centres and hospitals differ. Digital apps (Metrash, Hukoomi, Nar’aakom) are 24/7. Confirm before you travel. Hukoomi 109.", "summary_ar": "معظم مراكز الخدمة الحكومية تعمل الأحد–الخميس عادة 7:00–14:00. بعض المراكز والمستشفيات تختلف. التطبيقات (مترآش، حكومي، نرعاكم) على مدار الساعة. أكد قبل الذهاب. 109.", "steps_en": ["Use the ministry app first (Metrash, Hukoomi, Nar’aakom, Baladiya).", "If you must visit: Sunday–Thursday morning; bring QID.", "Hospitals and 999/991 emergencies are 24/7."], "steps_ar": ["استخدم التطبيق أولاً.", "إن لزم الحضور: الأحد–الخميس صباحاً مع الهوية.", "المستشفيات وطوارئ 999/991 على مدار الساعة."], "docs_en": ["QID"], "docs_ar": ["الهوية"], "where_en": ["hukoomi.gov.qa"], "contacts": ["109"], "kw": "government office working hours أوقات عمل الدوائر الحكومية ministry hours sunday thursday 7am"}, {"id": "qid-status-metrash", "name_en": "Check YOUR QID / visa status (Metrash only — this bot cannot see it)", "name_ar": "استعلام حالة الهوية / التأشيرة (فقط مطراش — هذا المساعد لا يراها)", "summary_en": "There is no public MOI API for your personal QID or visa. Nobody can sell a permanent live QID feed. Only YOU see the file after login on official Metrash (QID + SIM registered to that QID). This chatbot is unofficial and will never show your case number, expiry, or fines from a typed QID.", "summary_ar": "لا توجد واجهة عامة للداخلية لملف هويتك. لا يمكن بيع استعلام حي دائم. الملف تراه أنت فقط بعد الدخول على مطراش الرسمي (الهوية + شريحة مسجّلة عليها). هذا المساعد غير رسمي ولن يظهر صلاحيتك أو غراماتك من رقم تكتبه هنا.", "steps_en": ["Do not type your QID number here.", "Install official Metrash (publisher: Ministry of Interior). Metrash2 brand is retired.", "Login with your QID and the mobile SIM registered to that QID.", "Open Residency / QID to see expiry, applications, and delivery.", "Open Traffic for fines and black points.", "Hukoomi personal services: hukoomi.gov.qa → Sign in with Tawtheeq + QID.", "If the app fails: MOI 2366666 · Metrash 2342000 · Hukoomi 109."], "steps_ar": ["لا تكتب رقم الهوية هنا.", "حمّل مطراش الرسمي (الناشر: وزارة الداخلية). علامة مطراش2 ملغاة.", "ادخل بالهوية والشريحة المسجّلة عليها.", "الإقامة / الهوية: الصلاحية والطلبات والتوصيل.", "المرور: المخالفات والنقاط السوداء.", "خدمات حكومي الشخصية: hukoomi.gov.qa ← توثيق + الهوية.", "إن تعطل التطبيق: 2366666 · مطراش 2342000 · حكومي 109."], "docs_en": ["Your QID", "SIM registered to that QID"], "docs_ar": ["هويتك", "شريحة مسجّلة على الهوية"], "where_en": ["Official Metrash app", "https://portal.moi.gov.qa"], "contacts": ["MOI 2366666", "Metrash 2342000", "109"], "kw": "check my qid status visa status حالة الهوية استعلام إقامة live qid my file ملفي expiry انتهاء"}, {"id": "hukoomi-portal", "name_en": "Hukoomi official e-government portal map", "name_ar": "خريطة منصة حكومي الرسمية", "summary_en": "hukoomi.gov.qa is Qatar’s official digital government portal. This chatbot is unofficial and is NOT your QID login. Personal files still need Tawtheeq + QID on the real portal. Audience tabs: Citizens & Residents · Business Owners & Investors. Categories: Citizenship and Residency, Culture, Community, and Recreation, Education, Employment and Workplace, Environment and Agriculture, Health, Housing and Property, Legal Affairs and Justice, National Reports and Statistics, Religion and Islamic Affairs, Social Protection, Transportation. Life-moment journeys: Getting Married, Benefiting from Social Welfare, Managing My Retirement, Owning a Boat, Owning a Falcon. More will be added. Qatar for All: elderly, migrant workers, persons with disabilities, women, youth. Public population statistic on the homepage: 3.34M. Contact 109 in Qatar or +974 44069999. Latest public news: 2026-08-11: S'hail is accepting hunting-weapon licence applications via the official Metrash app until 18 August 2026. 2026-08-10: MCIT celebrated 10 companies completing the 3rd cohort of the Scale Now (Wasel / واصل) programme. 2026-08-09: MOI launched payment of financial claims via the MOI website and the official Metrash app. 2026-08-06: Ministry of Public Health launched an electronic system for controlled medicines for travellers. Featured event: Libraries Lead Forum 2026: Reimagining Libraries as Social Infrastructure — 14–15 October 2026 at Qatar National Library.", "summary_ar": "hukoomi.gov.qa منصة الخدمات الحكومية الرسمية لدولة قطر. هذا المساعد غير رسمي وليس تسجيل دخول بهويتك. ملفاتك الشخصية ما زالت تحتاج توثيق + بطاقة الهوية على المنصة الحقيقية. الجمهور: المواطنون والمقيمون · أصحاب الأعمال والمستثمرون. الفئات: الجنسية والإقامة، الثقافة والمجتمع والترفيه، التعليم، التوظيف وأماكن العمل، البيئة والزراعة، الصحة، الإسكان والعقارات، العدالة والشؤون القانونية، التقارير والإحصاءات الوطنية، الدين والشؤون الإسلامية، الحماية الاجتماعية، النقل والمواصلات. لحظات الحياة: الإقدام على الزواج، الانتفاع من الرعاية الاجتماعية، إدارة التقاعد، امتلاك قارب، امتلاك صقر. قطر للجميع: كبار القدر، العمالة الوافدة، ذوو الإعاقة، المرأة، الشباب. إحصاء السكان على الصفحة: 3.34M. اتصل بـ 109 أو ‎+974 44069999. آخر أخبار عامة: 2026-08-11: سهيل يستقبل طلبات تراخيص أسلحة الصيد عبر تطبيق مطراش حتى 18 أغسطس 2026. 2026-08-10: وزارة الاتصالات وتكنولوجيا المعلومات احتفت بتخريج 10 شركات ضمن الدورة الثالثة من برنامج واصل. 2026-08-09: الداخلية أطلقت خدمة سداد المطالبات المالية عبر موقعها الإلكتروني وتطبيق مطراش. 2026-08-06: وزارة الصحة العامة دشّنت النظام الإلكتروني للأدوية الخاضعة للرقابة للمسافرين. فعالية: منتدى المكتبات في الصدارة 2026: رؤية جديدة للمكتبات كمؤسسات للتنمية المجتمعية — 14–15 أكتوبر 2026 في مكتبة قطر الوطنية.", "steps_en": ["Open https://hukoomi.gov.qa (Arabic) or https://hukoomi.gov.qa/en (English).", "Search, or pick a category / life-moment journey.", "Sign in with Tawtheeq + QID only when the service needs your personal file.", "Or call 109 / +974 44069999.", "This assistant explains the public map — it cannot open your case."], "steps_ar": ["افتح hukoomi.gov.qa أو النسخة الإنجليزية /en.", "ابحث أو اختر فئة / لحظة حياة.", "سجّل عبر توثيق + الهوية فقط إذا احتاجت الخدمة ملفك الشخصي.", "أو اتصل بـ 109 / 44069999.", "هذا المساعد يشرح الخريطة العامة — لا يفتح معاملتك."], "docs_en": ["QID for logged-in Hukoomi / Metrash services"], "docs_ar": ["بطاقة الهوية لخدمات حكومي / مطراش المسجّلة"], "where_en": ["https://hukoomi.gov.qa", "https://hukoomi.gov.qa/en"], "contacts": ["109", "+974 44069999"], "kw": "hukoomi حكومي portal tawtheeq توثيق 109 44069999 life moments لحظات الحياة categories فئات map خريطة qatar for all قطر للجميع official e-government"}, {"id": "hukoomi-login", "name_en": "Hukoomi / Tawtheeq login (this bot is not your QID login)", "name_ar": "تسجيل حكومي / توثيق (هذا المساعد ليس دخول الهوية)", "summary_en": "Hukoomi and MOI personal case files need Tawtheeq (توثيق) plus a valid QID. Metrash needs QID + a SIM registered to that QID. This assistant cannot open, track, or change your file.", "summary_ar": "ملفاتك الشخصية على حكومي والداخلية تحتاج توثيق + بطاقة هوية سارية. مطراش يحتاج الهوية وشريحة مسجّلة عليها. هذا المساعد لا يفتح ملفك ولا يتتبع معاملتك.", "steps_en": ["Open https://hukoomi.gov.qa (Arabic) or https://hukoomi.gov.qa/en (English).", "Choose Sign in / تسجيل الدخول.", "Authenticate with Tawtheeq using your QID (and OTP on your registered mobile).", "Only then can you see personal applications, payments, and documents.", "For MOI residency/QID/traffic files use the official Metrash app the same way."], "steps_ar": ["افتح https://hukoomi.gov.qa أو النسخة الإنجليزية /en.", "اختر تسجيل الدخول.", "سجّل عبر توثيق ببطاقة الهوية ورمز الجوال المسجّل.", "بعدها فقط تظهر معاملاتك ومدفوعاتك ومستنداتك.", "لملفات الإقامة/الهوية/المرور استخدم تطبيق مطراش الرسمي بنفس الطريقة."], "docs_en": ["Valid QID", "Mobile number registered to that QID", "Tawtheeq enrolment"], "docs_ar": ["بطاقة هوية سارية", "رقم جوال مسجّل على الهوية", "تفعيل توثيق"], "where_en": ["https://hukoomi.gov.qa", "https://hukoomi.gov.qa/en"], "contacts": ["109", "+974 44069999"], "kw": "login tawtheeq توثيق تسجيل دخول qid هوية personal file ملفي الشخصي otp nas autenticate sign in حكومي hukoomi not official login"}, {"id": "hukoomi-news", "name_en": "Latest public Hukoomi news", "name_ar": "آخر أخبار منصة حكومي العامة", "summary_en": "Public headlines copied from hukoomi.gov.qa — not your private case. 2026-08-11: S'hail is accepting hunting-weapon licence applications via the official Metrash app until 18 August 2026. 2026-08-10: MCIT celebrated 10 companies completing the 3rd cohort of the Scale Now (Wasel / واصل) programme. 2026-08-09: MOI launched payment of financial claims via the MOI website and the official Metrash app. 2026-08-06: Ministry of Public Health launched an electronic system for controlled medicines for travellers. Featured event: Libraries Lead Forum 2026: Reimagining Libraries as Social Infrastructure — 14–15 October 2026 at Qatar National Library. Always verify the live page; this snapshot can lag if Cloudflare blocks automated fetch.", "summary_ar": "عناوين عامة من hukoomi.gov.qa — ليست ملفك الخاص. 2026-08-11: سهيل يستقبل طلبات تراخيص أسلحة الصيد عبر تطبيق مطراش حتى 18 أغسطس 2026. 2026-08-10: وزارة الاتصالات وتكنولوجيا المعلومات احتفت بتخريج 10 شركات ضمن الدورة الثالثة من برنامج واصل. 2026-08-09: الداخلية أطلقت خدمة سداد المطالبات المالية عبر موقعها الإلكتروني وتطبيق مطراش. 2026-08-06: وزارة الصحة العامة دشّنت النظام الإلكتروني للأدوية الخاضعة للرقابة للمسافرين. فعالية: منتدى المكتبات في الصدارة 2026: رؤية جديدة للمكتبات كمؤسسات للتنمية المجتمعية — 14–15 أكتوبر 2026 في مكتبة قطر الوطنية. أكد الصفحة الحية؛ قد يتأخر هذا الملخص إذا حجب كلاودفلير الجلب الآلي.", "steps_en": ["Read the public headline in this guide.", "Open https://hukoomi.gov.qa or /en → News to confirm.", "Apply on the official ministry channel named in the story (usually Metrash or MOI)."], "steps_ar": ["اقرأ العنوان العام هنا.", "افتح hukoomi.gov.qa ← الأخبار للتأكيد.", "قدّم عبر القناة الرسمية المذكورة (غالباً مطراش أو الداخلية)."], "docs_en": ["QID for logged-in Hukoomi / Metrash services"], "docs_ar": ["بطاقة الهوية لخدمات حكومي / مطراش المسجّلة"], "where_en": ["https://hukoomi.gov.qa", "https://hukoomi.gov.qa/en"], "contacts": ["109", "+974 44069999"], "kw": "hukoomi news أخبار حكومي headlines latest حدث فعالية events libraries lead"}, {"id": "hukoomi-life-moments", "name_en": "Hukoomi life-moment journeys", "name_ar": "لحظات الحياة على منصة حكومي", "summary_en": "Hukoomi groups related procedures into life-moment journeys so you finish a milestone in one path. Current journeys: Getting Married, Benefiting from Social Welfare, Managing My Retirement, Owning a Boat, Owning a Falcon. Stay tuned for more life moments that will be added soon. Each journey still ends on the responsible ministry (MOI, MOL, etc.). Personal steps need Tawtheeq + QID. This bot is unofficial.", "summary_ar": "تجمع حكومي المعاملات المرتبطة بمرحلة حياة في مسار واحد. المسارات الحالية: الإقدام على الزواج، الانتفاع من الرعاية الاجتماعية، إدارة التقاعد، امتلاك قارب، امتلاك صقر. ترقّب المزيد من لحظات الحياة التي سيتم إضافتها قريبًا. كل مسار ينتهي عند الجهة المسؤولة. الخطوات الشخصية تحتاج توثيق + الهوية.", "steps_en": ["Open Hukoomi → Life Moments.", "Pick Getting Married, Social Welfare, Retirement, Owning a Boat, or Owning a Falcon.", "Follow the official steps; sign in with Tawtheeq when asked."], "steps_ar": ["افتح حكومي ← لحظات الحياة.", "اختر الزواج أو الرعاية الاجتماعية أو التقاعد أو امتلاك قارب أو امتلاك صقر.", "اتبع الخطوات الرسمية وسجّل بتوثيق عند الطلب."], "docs_en": ["QID for logged-in Hukoomi / Metrash services"], "docs_ar": ["بطاقة الهوية لخدمات حكومي / مطراش المسجّلة"], "where_en": ["https://hukoomi.gov.qa", "https://hukoomi.gov.qa/en"], "contacts": ["109", "+974 44069999"], "kw": "life moments لحظات الحياة زواج تقاعد قارب صقر رعاية اجتماعية getting married retirement boat falcon social welfare"}, {"id": "qatar-for-all", "name_en": "Qatar for All (Hukoomi inclusion themes)", "name_ar": "قطر للجميع (محاور منصة حكومي)", "summary_en": "Hukoomi homepage section linking equal-opportunity themes to the SDGs. The Elderly: Qatar supports the elderly with care, inclusion, and health services. Migrant Workers: Fair wages, better conditions, legal rights; kafala system abolished for most private-sector workers. Persons with Disabilities: Laws, inclusive education, and assistive technology. Women: Education, jobs, and legal support toward gender equality. Youth: Education, jobs, and development programmes. Linked from https://hukoomi.gov.qa/en/sustainable-development-goals.", "summary_ar": "قسم في الصفحة الرئيسية يربط تكافؤ الفرص بأهداف التنمية المستدامة. كبار القَدْر: تدعم دولة قطر رفاهية كبار القدر عبر الرعاية الشاملة والاندماج الاجتماعي والخدمات الصحية. العمالة الوافدة: عززت قطر قوانين العمال المهاجرين، ضامنة أجورًا عادلة وظروف عمل جيدة، مع إلغاء نظام الكفالة. الأشخاص ذوو الإعاقة: دعم حقوق ذوي الإعاقة عبر القوانين والتعليم الشامل والتكنولوجيا المساعدة. المرأة: تمكين المرأة عبر التعليم وفرص العمل والدعم التشريعي. الشباب: الاستثمار في الشباب عبر التعليم والتوظيف والتنمية.", "steps_en": ["Open Hukoomi → Qatar for All.", "Choose Elderly, Migrant Workers, Persons with Disabilities, Women, or Youth.", "Follow the official service links; this guide is unofficial."], "steps_ar": ["افتح حكومي ← قطر للجميع.", "اختر كبار القدر أو العمالة الوافدة أو ذوي الإعاقة أو المرأة أو الشباب.", "اتبع الروابط الرسمية؛ هذا الدليل غير رسمي."], "docs_en": ["QID for logged-in Hukoomi / Metrash services"], "docs_ar": ["بطاقة الهوية لخدمات حكومي / مطراش المسجّلة"], "where_en": ["https://hukoomi.gov.qa", "https://hukoomi.gov.qa/en"], "contacts": ["109", "+974 44069999"], "kw": "qatar for all قطر للجميع elderly كبار القدر migrant workers عمالة وافدة disability إعاقة women المرأة youth الشباب sdg"}, {"id": "hunting-licence", "name_en": "S'hail hunting-weapon licence (Metrash, until 18 Aug 2026)", "name_ar": "ترخيص سلاح الصيد عبر سهيل / مطراش (حتى 18 أغسطس 2026)", "summary_en": "Public Hukoomi news dated 2026-08-11. S'hail is accepting hunting-weapon licence applications via the official Metrash app until 18 August 2026. This is a public announcement, not your personal case file. Apply only on the official channel named in the story.", "summary_ar": "خبر عام من حكومي بتاريخ 2026-08-11. سهيل يستقبل طلبات تراخيص أسلحة الصيد عبر تطبيق مطراش حتى 18 أغسطس 2026. إعلان عام وليس ملفك الشخصي. قدّم فقط عبر القناة الرسمية المذكورة.", "steps_en": ["Read the public notice (2026-08-11).", "Confirm on hukoomi.gov.qa → News.", "Complete the application on the official app/site named in the notice."], "steps_ar": ["اقرأ الإعلان العام (2026-08-11).", "أكد على حكومي ← الأخبار.", "أكمل الطلب عبر التطبيق/الموقع الرسمي المذكور."], "docs_en": ["QID for logged-in Hukoomi / Metrash services"], "docs_ar": ["بطاقة الهوية لخدمات حكومي / مطراش المسجّلة"], "where_en": ["https://hukoomi.gov.qa", "https://hukoomi.gov.qa/en"], "contacts": ["109", "+974 44069999"], "kw": "suhail s'hail سهيل hunting weapon licence رخصة صيد سلاح مطراش metrash 18 august 2026"}, {"id": "mcit-scale-now", "name_en": "MCIT Scale Now / Wasel programme (3rd cohort)", "name_ar": "برنامج واصل / Scale Now — الدورة الثالثة", "summary_en": "Public Hukoomi news dated 2026-08-10. MCIT celebrated 10 companies completing the 3rd cohort of the Scale Now (Wasel / واصل) programme. This is a public announcement, not your personal case file. Apply only on the official channel named in the story.", "summary_ar": "خبر عام من حكومي بتاريخ 2026-08-10. وزارة الاتصالات وتكنولوجيا المعلومات احتفت بتخريج 10 شركات ضمن الدورة الثالثة من برنامج واصل. إعلان عام وليس ملفك الشخصي. قدّم فقط عبر القناة الرسمية المذكورة.", "steps_en": ["Read the public notice (2026-08-10).", "Confirm on hukoomi.gov.qa → News.", "Complete the application on the official app/site named in the notice."], "steps_ar": ["اقرأ الإعلان العام (2026-08-10).", "أكد على حكومي ← الأخبار.", "أكمل الطلب عبر التطبيق/الموقع الرسمي المذكور."], "docs_en": ["QID for logged-in Hukoomi / Metrash services"], "docs_ar": ["بطاقة الهوية لخدمات حكومي / مطراش المسجّلة"], "where_en": ["https://hukoomi.gov.qa", "https://hukoomi.gov.qa/en"], "contacts": ["109", "+974 44069999"], "kw": "mcit scale now واصل وزارة الاتصالات شركات startups"}, {"id": "moi-financial-claims", "name_en": "MOI financial-claim payment (website + Metrash)", "name_ar": "سداد المطالبات المالية لوزارة الداخلية", "summary_en": "Public Hukoomi news dated 2026-08-09. MOI launched payment of financial claims via the MOI website and the official Metrash app. This is a public announcement, not your personal case file. Apply only on the official channel named in the story.", "summary_ar": "خبر عام من حكومي بتاريخ 2026-08-09. الداخلية أطلقت خدمة سداد المطالبات المالية عبر موقعها الإلكتروني وتطبيق مطراش. إعلان عام وليس ملفك الشخصي. قدّم فقط عبر القناة الرسمية المذكورة.", "steps_en": ["Read the public notice (2026-08-09).", "Confirm on hukoomi.gov.qa → News.", "Complete the application on the official app/site named in the notice."], "steps_ar": ["اقرأ الإعلان العام (2026-08-09).", "أكد على حكومي ← الأخبار.", "أكمل الطلب عبر التطبيق/الموقع الرسمي المذكور."], "docs_en": ["QID for logged-in Hukoomi / Metrash services"], "docs_ar": ["بطاقة الهوية لخدمات حكومي / مطراش المسجّلة"], "where_en": ["https://hukoomi.gov.qa", "https://hukoomi.gov.qa/en"], "contacts": ["109", "+974 44069999"], "kw": "moi financial claims مطالبات مالية سداد الداخلية مطراش"}, {"id": "controlled-medicines", "name_en": "MoPH controlled medicines for travellers (e-system)", "name_ar": "أدوية خاضعة للرقابة للمسافرين — نظام إلكتروني", "summary_en": "Public Hukoomi news dated 2026-08-06. Ministry of Public Health launched an electronic system for controlled medicines for travellers. This is a public announcement, not your personal case file. Apply only on the official channel named in the story.", "summary_ar": "خبر عام من حكومي بتاريخ 2026-08-06. وزارة الصحة العامة دشّنت النظام الإلكتروني للأدوية الخاضعة للرقابة للمسافرين. إعلان عام وليس ملفك الشخصي. قدّم فقط عبر القناة الرسمية المذكورة.", "steps_en": ["Read the public notice (2026-08-06).", "Confirm on hukoomi.gov.qa → News.", "Complete the application on the official app/site named in the notice."], "steps_ar": ["اقرأ الإعلان العام (2026-08-06).", "أكد على حكومي ← الأخبار.", "أكمل الطلب عبر التطبيق/الموقع الرسمي المذكور."], "docs_en": ["QID for logged-in Hukoomi / Metrash services"], "docs_ar": ["بطاقة الهوية لخدمات حكومي / مطراش المسجّلة"], "where_en": ["https://hukoomi.gov.qa", "https://hukoomi.gov.qa/en"], "contacts": ["109", "+974 44069999"], "kw": "moph controlled medicines أدوية خاضعة للرقابة مسافرين travellers narcotic"}, {"id": "libraries-lead-2026", "name_en": "Libraries Lead Forum 2026: Reimagining Libraries as Social Infrastructure — 14–1", "name_ar": "منتدى المكتبات في الصدارة 2026: رؤية جديدة للمكتبات كمؤسسات للتنمية المجتمعية — ", "summary_en": "Libraries Lead Forum 2026: Reimagining Libraries as Social Infrastructure — 14–15 October 2026 at Qatar National Library. Venue: Qatar National Library (QNL). Listed on Hukoomi featured events.", "summary_ar": "منتدى المكتبات في الصدارة 2026: رؤية جديدة للمكتبات كمؤسسات للتنمية المجتمعية — 14–15 أكتوبر 2026 في مكتبة قطر الوطنية. المكان: مكتبة قطر الوطنية. من فعاليات حكومي المميزة.", "steps_en": ["Check dates on hukoomi.gov.qa → Events.", "Register with the host named on the official page."], "steps_ar": ["راجع التواريخ على حكومي ← الفعاليات.", "سجّل لدى الجهة المستضيفة المذكورة رسمياً."], "docs_en": ["QID for logged-in Hukoomi / Metrash services"], "docs_ar": ["بطاقة الهوية لخدمات حكومي / مطراش المسجّلة"], "where_en": ["https://hukoomi.gov.qa", "https://hukoomi.gov.qa/en"], "contacts": ["109", "+974 44069999"], "kw": "event فعالية Libraries Lead Forum 2026: Reimagining Libraries as Social Infrastructure — 14–15 October 2026 at Qatar National Library. منتدى المكتبات في الصدارة 2026: رؤية جديدة للمكتبات كمؤسسات للتنمية المجتمعية — 14–15 أكتوبر 2026 في مكتبة قطر الوطنية. Qatar National Library (QNL)"}];